type Page = 'dashboard' | 'policies' | 'new-policy' | 'customers' | 'insured-customers' | 'auto-register' | 'damage' | 'new-damage' | 'accounting' | 'production' | 'reconciliation' | 'agencies' | 'agency-management' | 'external-agencies' | 'agency-settings' | 'receivables' | 'staff' | 'calendar' | 'settings' | 'companies' | 'branches' | 'banks' | 'sub-agents' | 'quotes' | 'lost-customers' | 'reminders' | 'account-statement';

const parseAmount = (value: string) => { const normalized = value.trim().replace(/\s/g, ''); if (!normalized) return 0; const lastComma = normalized.lastIndexOf(','); const lastDot = normalized.lastIndexOf('.'); if (lastComma >= 0 && lastDot >= 0) return Number(lastComma > lastDot ? normalized.replace(/\./g, '').replace(',', '.') : normalized.replace(/,/g, '')); if (lastComma >= 0) return Number(normalized.replace(',', '.')); return Number(normalized); };
type Agency = { id: string; name: string; commission_rate?: number; is_external?: boolean; created_at?: string };
type Payment = { id: string; policy_id: string; amount: number; note: string; paid_at: string };
type BackupData = { exportedAt: string; policies: Policy[]; customers: Customer[]; agencies: Agency[]; payments: Payment[]; accounting: Record<string, unknown>[]; additional: Record<string, Record<string, unknown>[]> };

const agencyNames = ['SİGORTALİA', 'BİC SİGORTA', 'SHOWROOM SİGORTA', 'HÜDAYİ AKDEMİR SİGORTA', 'SİGORTA EVRENİ', 'BAHA SİGORTA', 'İDS SİGORTA', 'KARUN SİGORTA'];
const DEFAULT_COMMISSION_RATE = 0.06;
const commissionRateFor = (agency: Agency) => agency.commission_rate != null ? Number(agency.commission_rate) / 100 : DEFAULT_COMMISSION_RATE;
const commissionFor = (policy: Policy, agencies: Agency[]) => { if (policy.uretim_tipi === 'dis') return 0; const agency = agencies.find(a => a.id === policy.agency_id); if (!agency) return 0; return Number(policy.net_prim || 0) * commissionRateFor(agency); };
const money = (value: number) => new Intl.NumberFormat('tr-TR', { style: 'currency', currency: 'TRY', maximumFractionDigits: 0 }).format(value || 0);
const dateBeforeOneYear = (date: string) => { if (!date) return ''; const d = new Date(`${date}T00:00:00`); d.setDate(d.getDate() - 365); return d.toISOString().slice(0, 10); };
const dateDiff = (date: string) => Math.ceil((new Date(`${date}T00:00:00`).getTime() - new Date().setHours(0, 0, 0, 0)) / 86400000);

function AuthScreen({ onDone }: { onDone: () => void }) { const [signUp, setSignUp] = useState(false); const [forgot, setForgot] = useState(false); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [name, setName] = useState(''); const [error, setError] = useState(''); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false); async function submit(event: FormEvent) { event.preventDefault(); setBusy(true); setError(''); setMessage(''); if (signUp) { const result = await supabase.auth.signUp({ email, password, options: { data: { full_name: name } } }); setBusy(false); if (result.error) { console.error('Kayıt hatası:', result.error); const msg = result.error.message; if (msg.includes('already registered') || msg.includes('already been registered')) setError('Bu e-posta adresi zaten kayıtlı. Giriş yapmayı deneyin veya şifrenizi sıfırlayın.'); else if (msg.includes('password')) setError('Şifre en az 6 karakter olmalıdır.'); else if (msg.includes('email')) setError('Geçerli bir e-posta adresi girin.'); else setError('Kayıt yapılamadı: ' + msg); } else if (result.data?.user && !result.data?.session) { setError(''); setMessage('Hesabınız oluşturuldu! E-posta adresinize gönderilen doğrulama bağlantısına tıklayın, ardından giriş yapın. Doğrulama gerektirmiyorsa doğrudan giriş yapabilirsiniz.'); } else { onDone(); } } else { const result = await supabase.auth.signInWithPassword({ email, password }); setBusy(false); if (result.error) { console.error('Giriş hatası:', result.error); const msg = result.error.message; if (msg.includes('Invalid login credentials')) setError('E-posta veya şifre hatalı. Bilgilerinizi kontrol edin. Hesabınız yoksa "Yeni hesap oluştur" seçeneğini kullanın.'); else if (msg.includes('Email not confirmed')) setError('E-posta adresiniz henüz doğrulanmamış. Lütfen e-postanıza gönderilen doğrulama bağlantısına tıklayın.'); else if (msg.includes('rate limit') || msg.includes('too many')) setError('Çok fazla deneme yapıldı. Lütfen birkaç dakika bekleyip tekrar deneyin.'); else setError('Giriş yapılamadı: ' + msg); } else onDone(); } } async function sendReset(event: FormEvent) { event.preventDefault(); setBusy(true); setError(''); const result = await supabase.auth.resetPasswordForEmail(email, { redirectTo: `${window.location.origin}/reset-password` }); setBusy(false); if (result.error) setError('Sıfırlama bağlantısı gönderilemedi.'); else setMessage('Şifre sıfırlama bağlantısı e-posta adresinize gönderildi.'); } return <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 relative overflow-hidden"><div className="absolute inset-0 bg-[radial-gradient(circle_at_70%_20%,rgba(37,99,235,.18),transparent_34%)]" /><div className="w-full max-w-md relative"><div className="text-center mb-8"><div className="mx-auto size-14 rounded-2xl bg-blue-600 flex items-center justify-center shadow-xl shadow-blue-900/50"><ShieldCheck className="text-white size-8" /></div><h1 className="text-white text-3xl font-bold mt-5">Poliçe Takip Sistemi</h1><p className="text-slate-400 mt-2">Sigorta acente yönetim platformu</p></div><form onSubmit={submit} className="bg-white rounded-2xl p-7 shadow-2xl"><h2 className="text-xl font-bold text-slate-900">{signUp ? 'Yeni hesap oluştur' : 'Hoş geldiniz'}</h2><p className="text-sm text-slate-500 mt-1 mb-6">{signUp ? 'Acentenizi yönetmeye başlayın.' : 'Hesabınıza giriş yapın.'}</p>{signUp && <label className="field">Ad Soyad<input required value={name} onChange={e => setName(e.target.value)} /></label>}<label className="field">E-posta<input required type="email" value={email} onChange={e => setEmail(e.target.value)} /></label><label className="field">Şifre<input required minLength={6} type="password" value={password} onChange={e => setPassword(e.target.value)} /></label>{error && <div className="text-sm text-red-600 bg-red-50 rounded-lg p-3 mb-4">{error}</div>}{message && <div className="text-sm text-emerald-700 bg-emerald-50 rounded-lg p-3 mb-4">{message}</div>}<button disabled={busy} className="w-full bg-blue-700 hover:bg-blue-800 disabled:opacity-60 text-white py-3 rounded-xl font-semibold">{busy ? 'Bekleyin...' : signUp ? 'Hesap Oluştur' : 'Giriş Yap'}</button>{!signUp && <button type="button" onClick={() => { setForgot(true); setError(''); setMessage(''); }} className="w-full text-sm text-blue-700 hover:text-blue-900 mt-4">Şifremi Unuttum?</button>}<button type="button" onClick={() => { setSignUp(!signUp); setError(''); setMessage(''); }} className="w-full text-sm text-slate-500 hover:text-teal-700 mt-3">{signUp ? 'Zaten hesabım var' : 'Yeni hesap oluştur'}</button></form></div>{forgot && <div className="modal-backdrop"><form onSubmit={sendReset} className="modal"><div className="flex justify-between items-center mb-5"><h3 className="font-bold text-lg">Şifre Sıfırlama</h3><button type="button" onClick={() => setForgot(false)}><X size={19} /></button></div><p className="text-sm text-slate-500 mb-4">E-posta adresinizi girin, size güvenli bir sıfırlama bağlantısı gönderelim.</p><label className="field">E-posta<input required type="email" value={email} onChange={e => setEmail(e.target.value)} /></label>{error && <div className="text-sm text-red-600 bg-red-50 rounded-lg p-3 mt-3">{error}</div>}{message && <div className="text-sm text-emerald-700 bg-emerald-50 rounded-lg p-3 mt-3">{message}</div>}<button disabled={busy} className="btn-primary w-full mt-4">Bağlantı Gönder</button></form></div>}</div> }
function ResetPasswordScreen() { const [password, setPassword] = useState(''); const [confirm, setConfirm] = useState(''); const [error, setError] = useState(''); const [done, setDone] = useState(false); async function submit(event: FormEvent) { event.preventDefault(); if (password.length < 6 || password !== confirm) { setError(password.length < 6 ? 'Şifre en az 6 karakter olmalı.' : 'Şifreler eşleşmiyor.'); return; } const result = await supabase.auth.updateUser({ password }); if (result.error) setError('Şifre güncellenemedi.'); else { setDone(true); window.setTimeout(() => { window.location.href = '/'; }, 1200); } } return <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6"><form onSubmit={submit} className="bg-white rounded-2xl p-7 shadow-2xl w-full max-w-md"><h2 className="text-xl font-bold text-slate-900">Yeni Şifre Belirle</h2><p className="text-sm text-slate-500 mt-1 mb-6">Hesabınız için yeni bir şifre oluşturun.</p><label className="field">Yeni Şifre<input required minLength={6} type="password" value={password} onChange={e => setPassword(e.target.value)} /></label><label className="field">Yeni Şifre Tekrar<input required minLength={6} type="password" value={confirm} onChange={e => setConfirm(e.target.value)} /></label>{error && <div className="text-sm text-red-600 bg-red-50 rounded-lg p-3 mb-4">{error}</div>}{done && <div className="text-sm text-emerald-700 bg-emerald-50 rounded-lg p-3 mb-4">Şifreniz güncellendi. Giriş ekranına yönlendiriliyorsunuz.</div>}<button disabled={done} className="btn-primary w-full">Şifreyi Güncelle</button></form></div> }

function Sidebar({ page, setPage, onLogout, userName, agencyProfile, collapsed, onToggleCollapse }: { page: Page; setPage: (page: Page) => void; onLogout: () => void; userName: string; agencyProfile: AgencyProfile | null; collapsed: boolean; onToggleCollapse: () => void }) { const [open, setOpen] = useState<Record<string, boolean>>({ policies: true, customers: true, reports: true, tanimlama: true }); const item = (id: Page, label: string, Icon: typeof LayoutDashboard) => <button onClick={() => setPage(id)} className={`side-item ${page === id ? 'active' : ''}`} title={label}><Icon size={18} /><span>{label}</span></button>; const group = (key: string, label: string, Icon: typeof LayoutDashboard, children: [Page, string][]) => <div><button onClick={() => setOpen(v => ({ ...v, [key]: !v[key] }))} className="side-item" title={label}><Icon size={18} /><span className="flex-1 text-left">{label}</span>{open[key] ? <ChevronDown size={15} className="side-group-arrow" /> : <ChevronRight size={15} className="side-group-arrow" />}</button>{open[key] && <div className="ml-8 border-l border-slate-700 pl-2 space-y-1">{children.map(([id, text]) => <button key={id} onClick={() => setPage(id)} className={`sub-item ${page === id ? 'selected' : ''}`}>{text}</button>)}</div>}</div>; return <aside className={`sidebar ${collapsed ? 'collapsed' : ''}`}><div className="px-3 h-20 flex items-center gap-3 border-b border-slate-800"><div className="size-9 rounded-xl bg-blue-600 flex items-center justify-center flex-shrink-0 overflow-hidden">{agencyProfile?.logo_path ? <img src={supabase.storage.from('agency-logos').getPublicUrl(agencyProfile.logo_path).data.publicUrl} alt={agencyProfile.name} className="w-full h-full object-contain bg-white" /> : <ShieldCheck size={23} className="text-white" />}</div><div className="side-user-info min-w-0"><div className="text-white font-bold truncate max-w-40">Poliçe Takip</div><div className="text-[10px] text-slate-400 tracking-wider truncate">{agencyProfile?.name || userName}</div></div><button onClick={onToggleCollapse} className="sidebar-toggle ml-auto" title={collapsed ? 'Menüyü Genişlet' : 'Menüyü Daralt'}>{collapsed ? <ChevronRight size={18} /> : <ChevronLeft size={18} />}</button></div><div className="p-3 space-y-1 overflow-y-auto flex-1"><div className="nav-label">GENEL</div>{item('dashboard', 'Dashboard', LayoutDashboard)}<div className="nav-label mt-5">YÖNETİM</div>{item('quotes', 'Teklifler', FileSpreadsheet)}{group('policies', 'Poliçe İşlemleri', ClipboardList, [['new-policy', 'Yeni Poliçe Ekle'], ['policies', 'Tüm Poliçeler']])}{group('customers', 'Müşteri İşlemleri', Users, [['auto-register', 'Otomatik Kayıt'], ['customers', 'Kayıtlı Müşteriler'], ['insured-customers', 'Poliçesi Bulunanlar'], ['lost-customers', 'Kaçan Müşteriler']])}{item('accounting', 'Muhasebe', CircleDollarSign)}{item('agency-settings', 'Acente Ayarları', UserCircle)}<div className="nav-label mt-5">RAPORLAMA</div>{group('reports', 'Raporlar', BarChart3, [['production', 'Üretim Sorgula'], ['reconciliation', 'Mutabakat Raporu'], ['agencies', 'Acenteler'], ['receivables', 'Verecekler']])}<div className="nav-label mt-5">TANIMLAMA</div>{group('tanimlama', 'Tanımlama', Building2, [['companies', 'Şirketler'], ['branches', 'Branşlar'], ['banks', 'Bankalar'], ['sub-agents', 'Taliler'], ['agency-management', 'Acente Yönetimi'], ['external-agencies', 'Dış Acenteler']])}<div className="nav-label mt-5">DİĞER</div>{group('damage', 'Araç Hasar Kaydı', Truck, [['new-damage', 'Hasar Kaydı Ekle'], ['damage', 'Hasar Kayıtları']])}{item('reminders', 'Hatırlatmalar', Bell)}{item('account-statement', 'Hesap Ekstresi', FileText)}{item('staff', 'Personel İşlemleri', UserCircle)}</div><div className="p-3 border-t border-slate-800"><button onClick={() => setPage('settings')} className="side-item"><Settings size={18} /><span>Ayarlar</span></button><button onClick={onLogout} className="side-item text-slate-400 hover:text-red-300"><LogOut size={18} /><span>Çıkış Yap</span></button></div></aside> }
function TopBar({ page, userName, darkMode, onToggleTheme, policies, onNavigate, agencyProfile }: { page: Page; userName: string; darkMode: boolean; onToggleTheme: () => void; policies: Policy[]; onNavigate: (id: string) => void; agencyProfile: AgencyProfile | null }) { const labels: Record<Page, string> = { dashboard: 'Dashboard', policies: 'Tüm Poliçeler', 'new-policy': 'Yeni Poliçe Ekle', customers: 'Kayıtlı Müşteriler', 'insured-customers': 'Poliçesi Bulunanlar', 'auto-register': 'Otomatik Kayıt', damage: 'Hasar Kayıtları', 'new-damage': 'Hasar Kaydı Ekle', accounting: 'Muhasebe', production: 'Üretim Sorgula', reconciliation: 'Mutabakat Raporu', agencies: 'Acente Raporları', 'agency-management': 'Acente Yönetimi', 'external-agencies': 'Dış Acente Yönetimi', receivables: 'Verecekler', staff: 'Personel İşlemleri', calendar: 'Takvim', settings: 'Ayarlar', 'agency-settings': 'Acente Ayarları', companies: 'Sigorta Şirketleri', branches: 'Branşlar', banks: 'Banka Hesapları', 'sub-agents': 'Tali Acenteler', quotes: 'Teklifler', 'lost-customers': 'Kaçan Müşteriler', reminders: 'Hatırlatmalar', 'account-statement': 'Hesap Ekstresi' }; return <header className="topbar"><div className="flex items-center gap-3"><button className="mobile-menu"><Menu size={21} /></button><div><p className="text-xs text-slate-400">Yönetim Paneli / {labels[page]}</p><h1 className="text-lg font-bold text-slate-900">{labels[page]}</h1></div></div><div className="flex items-center gap-3"><button type="button" onClick={onToggleTheme} className="icon-btn" title={darkMode ? 'Aydınlık moda geç' : 'Karanlık moda geç'}>{darkMode ? <Sun size={18} /> : <Moon size={18} />}</button><NotificationBell policies={policies} onNavigate={onNavigate} /><div className="h-8 w-px bg-slate-200" /><div className="flex items-center gap-2">{agencyProfile?.logo_path ? <img src={supabase.storage.from('agency-logos').getPublicUrl(agencyProfile.logo_path).data.publicUrl} alt={agencyProfile.name} className="size-9 rounded-lg object-contain" /> : <div className="size-9 bg-blue-100 rounded-full flex items-center justify-center text-blue-800"><Check size={19} /></div>}<div className="hidden sm:block"><div className="font-semibold text-sm">{agencyProfile?.name?.trim() || userName}</div><div className="text-[11px] text-slate-400">Yetkili</div></div></div></div></header> }
function PageTitle({ title, subtitle, action }: { title: string; subtitle?: string; action?: ReactNode }) { return <div className="flex flex-wrap items-start justify-between gap-4 mb-6"><div><h2 className="text-2xl font-bold text-slate-900 tracking-tight">{title}</h2>{subtitle && <p className="text-sm text-slate-500 mt-1">{subtitle}</p>}</div>{action}</div> }
function StatCard({ title, value, detail, icon: Icon, tone }: { title: string; value: string; detail: string; icon: typeof Activity; tone: string }) { return <div className="card p-5"><div className="flex items-start justify-between"><div><p className="text-xs font-semibold text-slate-500 uppercase tracking-wider">{title}</p><p className="text-2xl font-bold text-slate-900 mt-3">{value}</p><p className="text-xs text-slate-500 mt-2 flex items-center gap-1"><ArrowUpRight size={13} className="text-emerald-600" />{detail}</p></div><div className={`size-11 rounded-xl flex items-center justify-center ${tone}`}><Icon size={21} /></div></div></div> }

function Dashboard({ setPage, policies, customers, agencies }: { setPage: (p: Page) => void; policies: Policy[]; customers: Customer[]; agencies: Agency[] }) { const [filterMonth, setFilterMonth] = useState(''); const [filterYear, setFilterYear] = useState(''); const [chartMonth, setChartMonth] = useState(''); const [chartYear, setChartYear] = useState(''); const periodPolicies = policies.filter(p => { const dateStr = p.baslangic_tarihi || p.tanzim_tarihi || p.bitis_tarihi || p.created_at; const d = new Date(dateStr); if (isNaN(d.getTime())) return true; return (!filterMonth || String(d.getMonth()) === filterMonth) && (!filterYear || String(d.getFullYear()) === filterYear); }); const chartPolicies = policies.filter(p => { const dateStr = p.baslangic_tarihi || p.tanzim_tarihi || p.bitis_tarihi || p.created_at; const d = new Date(dateStr); if (isNaN(d.getTime())) return true; return (!chartMonth || String(d.getMonth()) === chartMonth) && (!chartYear || String(d.getFullYear()) === chartYear); }); const signedNet = (p: Policy) => p.record_type === 'iadeli_zeyil' ? -Number(p.net_prim || 0) : Number(p.net_prim || 0); const signedGross = (p: Policy) => p.record_type === 'iadeli_zeyil' ? -Number(p.brut_prim || 0) : Number(p.brut_prim || 0); const net = periodPolicies.filter(p => !p.iptal && p.uretim_tipi !== 'dis').reduce((a, p) => a + signedNet(p), 0); const gross = periodPolicies.filter(p => !p.iptal && p.uretim_tipi !== 'dis').reduce((a, p) => a + signedGross(p), 0); const due = periodPolicies.filter(p => !p.iptal && p.odeme_durumu === 'verecek' && p.uretim_tipi !== 'dis').reduce((a, p) => a + signedGross(p), 0); const totalCommission = periodPolicies.filter(p => !p.iptal && p.uretim_tipi !== 'dis').reduce((a, p) => a + (p.record_type === 'iadeli_zeyil' ? -commissionFor(p, agencies) : commissionFor(p, agencies)), 0); const expiring = periodPolicies.filter(p => !p.iptal && p.bitis_tarihi && dateDiff(p.bitis_tarihi) >= 0 && dateDiff(p.bitis_tarihi) <= 14).sort((a, b) => dateDiff(a.bitis_tarihi) - dateDiff(b.bitis_tarihi)); const types: Record<string, string> = { TRAFİK: '#b5e45a', KASKO: '#f5a33b', 'MESLEKİ SORUMLULUK': '#4b4cff', İMM: '#e4dfb1', 'FERDİ KAZA': '#800000', DASK: '#a9a9a9', KONUT: '#e6a8c2' }; const cancelledColor = '#FF0000'; const pieSegments = Object.entries(types).map(([type, color]) => ({ label: type, color, value: chartPolicies.filter(p => !p.iptal && (p.sigorta_turu || '').toUpperCase().includes(type)).length })); const companyColors = ['#0d9488','#2563eb','#f59e0b','#dc2626','#7c3aed','#059669','#db2777','#0891b2','#65a30d','#ea580c','#4f46e5','#0284c7','#c026d3','#16a34a','#e11d48','#9333ea']; const companyMap: Record<string, number> = {}; chartPolicies.filter(p => !p.iptal).forEach(p => { const name = p.sigorta_sirketi || 'Bilinmiyor'; companyMap[name] = (companyMap[name] || 0) + 1; }); const companySegments = Object.entries(companyMap).sort((a,b) => b[1]-a[1]).map(([name, value], i) => ({ label: name, value, color: companyColors[i % companyColors.length] })); const months = Array.from({ length: 12 }, (_, i) => i); const yearly = months.map(month => periodPolicies.filter(p => new Date(p.baslangic_tarihi || p.tanzim_tarihi || p.bitis_tarihi || p.created_at).getMonth() === month)); const maxMonth = Math.max(...yearly.map(rows => rows.length), 1); const periodLabel = !filterMonth && !filterYear ? 'Tüm zamanlar' : !filterMonth ? filterYear : !filterYear ? `${['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık'][Number(filterMonth)]}` : `${['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık'][Number(filterMonth)]} ${filterYear}`; return <div><PageTitle title="Genel Bakış" subtitle="Yıllık acente performans özeti." action={<button onClick={() => setPage('new-policy')} className="btn-primary"><Plus size={17} /> Yeni Üretim</button>} /><div className="card mb-5"><div className="flex items-center gap-2 text-slate-600 p-3 flex-wrap"><Filter size={14} /> <span className="text-sm font-semibold">Prim Filtreleme</span><span className="text-xs text-slate-400 ml-1">({periodLabel})</span><div className="flex items-center gap-2 ml-auto"><label className="flex items-center gap-1.5 text-xs font-semibold text-slate-600"><span>Ay:</span><select value={filterMonth} onChange={e => setFilterMonth(e.target.value)} className="dark-select border border-slate-200 rounded-lg px-2 py-1.5 text-xs bg-white"><option value="">Tümü</option>{Array.from({ length: 12 }, (_, index) => <option key={index} value={String(index)}>{new Intl.DateTimeFormat('tr-TR', { month: 'long' }).format(new Date(2020, index, 1))}</option>)}</select></label><label className="flex items-center gap-1.5 text-xs font-semibold text-slate-600"><span>Yıl:</span><select value={filterYear} onChange={e => setFilterYear(e.target.value)} className="dark-select border border-slate-200 rounded-lg px-2 py-1.5 text-xs bg-white"><option value="">Tümü</option>{Array.from({ length: 2040 - new Date().getFullYear() + 1 }, (_, index) => { const value = String(new Date().getFullYear() - 2 + index); return <option key={value} value={value}>{value}</option>; })}</select></label></div></div></div><div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mb-6"><StatCard title="Net Prim" value={money(net)} detail={`${periodPolicies.filter(p => !p.iptal).length} üretim`} icon={CircleDollarSign} tone="bg-teal-50 text-teal-700" /><StatCard title="Brüt Prim" value={money(gross)} detail="İptaller düşülmüş" icon={Receipt} tone="bg-blue-50 text-blue-700" /><StatCard title="Müşteriler" value={customers.length.toString()} detail="Kayıtlı müşteri" icon={Users} tone="bg-amber-50 text-amber-700" /><StatCard title="Verecekler" value={money(due)} detail="Tahsilat bekleyen" icon={AlertTriangle} tone="bg-red-50 text-red-700" /></div><div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mb-6"><StatCard title="Toplam Komisyon" value={money(totalCommission)} detail="Net prim üzerinden" icon={CircleDollarSign} tone="bg-emerald-50 text-emerald-700" /></div><div className="grid grid-cols-1 xl:grid-cols-3 gap-5"><div className="card xl:col-span-2 overflow-hidden"><div className="teal-strip"><span>Aylık Üretim Özeti</span><button onClick={() => setPage('production')}>Detaylı Görüntüle <ArrowUpRight size={14} /></button></div><div className="p-5"><div className="flex items-end justify-between gap-2 h-52">{yearly.map((rows, i) => <div className="flex-1 flex flex-col items-center gap-2" key={i}><div className="w-full flex items-end justify-center h-40"><div className="w-5 max-w-full flex flex-col-reverse overflow-hidden rounded-t-md" style={{ height: `${rows.length / maxMonth * 100}%`, minHeight: rows.length ? 8 : 0 }}>{Object.entries(types).map(([type, color]) => { const count = rows.filter(p => !p.iptal && (p.sigorta_turu || '').toUpperCase().includes(type)).length; return count ? <div key={type} style={{ height: `${count / rows.length * 100}%`, backgroundColor: color }} /> : null })}{rows.some(p => p.iptal) && <div style={{ height: `${rows.filter(p => p.iptal).length / rows.length * 100}%`, backgroundColor: cancelledColor }} />}</div></div><span className="text-[10px] text-slate-400">{['Oca','Şub','Mar','Nis','May','Haz','Tem','Ağu','Eyl','Eki','Kas','Ara'][i]}</span></div>)}</div></div></div><div className="card overflow-hidden"><div className="teal-strip"><span>Yaklaşan Hatırlatmalar</span><button onClick={() => setPage('reminders')}>Tümü <ArrowUpRight size={14} /></button></div><div className="p-2">{expiring.length ? expiring.map(p => <div className="flex gap-3 p-3 border-b border-slate-100" key={p.id}><div className="size-9 rounded-lg flex items-center justify-center bg-red-50 text-red-600"><Bell size={16} /></div><div><p className="text-sm font-semibold text-slate-800">{p.musteri_adi} poliçe yenilemesi</p><p className="text-xs text-red-500 mt-1">{dateDiff(p.bitis_tarihi)} gün kaldı · {p.bitis_tarihi}</p></div></div>) : <div className="empty">14 gün içinde bitecek poliçe yok.</div>}</div></div></div><div className="card mt-5"><div className="teal-strip"><span>Dağılım Grafikleri</span><div className="flex items-center gap-2"><Filter size={14} /><label className="flex items-center gap-1.5 text-xs font-semibold text-white"><span>Ay:</span><select value={chartMonth} onChange={e => setChartMonth(e.target.value)} className="dark-select border border-white/30 rounded-lg px-2 py-1.5 text-xs bg-white/10 text-white"><option value="" className="text-slate-800">Tümü</option>{Array.from({ length: 12 }, (_, index) => <option key={index} value={String(index)} className="text-slate-800">{new Intl.DateTimeFormat('tr-TR', { month: 'long' }).format(new Date(2020, index, 1))}</option>)}</select></label><label className="flex items-center gap-1.5 text-xs font-semibold text-white"><span>Yıl:</span><select value={chartYear} onChange={e => setChartYear(e.target.value)} className="dark-select border border-white/30 rounded-lg px-2 py-1.5 text-xs bg-white/10 text-white"><option value="" className="text-slate-800">Tümü</option>{Array.from({ length: 2040 - new Date().getFullYear() + 1 }, (_, index) => { const value = String(new Date().getFullYear() - 2 + index); return <option key={value} value={value} className="text-slate-800">{value}</option>; })}</select></label></div></div><div className="grid grid-cols-1 lg:grid-cols-2 gap-5 p-5"><div className="flex flex-col items-center"><h4 className="text-sm font-semibold text-slate-700 mb-3">Sigorta Şirketi Dağılımı</h4><PieChart segments={companySegments} title="Sigorta Şirketi Dağılımı" /></div><div className="flex flex-col items-center"><h4 className="text-sm font-semibold text-slate-700 mb-3">Poliçe Türü Dağılımı</h4><PieChart segments={pieSegments} title="Poliçe Türü Dağılımı" /></div></div></div></div> }

function normalizeTr(s: string) { return s.replace(/İ/g,'I').replace(/ı/g,'i').replace(/Ş/g,'S').replace(/ş/g,'s').replace(/Ğ/g,'G').replace(/ğ/g,'g').replace(/Ç/g,'C').replace(/ç/g,'c').replace(/Ü/g,'U').replace(/ü/g,'u').replace(/Ö/g,'O').replace(/ö/g,'o').replace(/\s+/g,' ').trim().toLowerCase(); }
function PolicyForm({ onSaved, agencies: agencyList, policy, policies, companies, branches, bankAccounts }: { onSaved: () => void; agencies: Agency[]; policy?: Policy; policies: Policy[]; companies: InsuranceCompany[]; branches: InsuranceBranch[]; bankAccounts: BankAccount[] }) { const [form, setForm] = useState({ record_type: policy?.record_type || 'uretim', sigorta_sirketi: (() => { const name = policy?.sigorta_sirketi || ''; if (!name) return ''; const exact = companies.find(c => c.name === name); if (exact) return exact.name; const norm = normalizeTr(name); const fuzzy = companies.find(c => normalizeTr(c.name) === norm); return fuzzy ? fuzzy.name : name; })(), musteri_adi: policy?.musteri_adi || '', police_no: policy?.police_no || '', plaka: policy?.plaka || '', net_prim: String(policy?.net_prim || ''), brut_prim: String(policy?.brut_prim || ''), bitis_tarihi: policy?.bitis_tarihi || '', tanzim_tarihi: policy?.tanzim_tarihi || new Date().toISOString().slice(0, 10), sigorta_turu: policy?.sigorta_turu || '', branch_group: policy?.branch_group || '', agency_id: policy?.agency_id || '', odeme_durumu: policy?.odeme_durumu || 'verecek', payment_method: policy?.payment_method || 'Nakit', uretim_tipi: policy?.uretim_tipi || 'ic', aciklama: policy?.aciklama || '', bank_account_id: policy?.bank_account_id || '', issuing_agency_id: policy?.issuing_agency_id || '' }); const [file, setFile] = useState<File | null>(null); const [saving, setSaving] = useState(false); const [dupError, setDupError] = useState(''); const [selectedBankName, setSelectedBankName] = useState(() => policy?.bank_account_id ? bankAccounts.find(b => b.id === policy.bank_account_id)?.bank_name || '' : ''); const update = (key: string, value: string) => { setForm(v => ({ ...v, [key]: value })); if (key === 'police_no') setDupError(''); if (key === 'branch_group') setForm(v => ({ ...v, branch_group: value, sigorta_turu: '' })); if (key === 'uretim_tipi') setForm(v => ({ ...v, uretim_tipi: value, agency_id: '' })); }; const filteredBranches = form.branch_group ? branches.filter(b => b.branch_group === form.branch_group) : branches; const uniqueBankNames = [...new Set(bankAccounts.map(b => b.bank_name))]; const accountsForBank = selectedBankName ? bankAccounts.filter(b => b.bank_name === selectedBankName) : []; const agencyOptions = form.uretim_tipi === 'dis' ? agencyList.filter(a => a.is_external) : agencyList.filter(a => !a.is_external); async function submit(e: FormEvent) { e.preventDefault(); if (form.police_no) { const dup = policies.some(p => p.police_no === form.police_no && p.id !== policy?.id); if (dup) { setDupError('Aynı poliçeyi iki kez girmeye çalışıyorsunuz. Bu poliçe no zaten kayıtlı.'); setSaving(false); return; } } setDupError(''); setSaving(true); const payload = { ...form, baslangic_tarihi: dateBeforeOneYear(form.bitis_tarihi), net_prim: parseAmount(form.net_prim), brut_prim: parseAmount(form.brut_prim), agency_id: form.uretim_tipi === 'dis' ? (form.issuing_agency_id || null) : (form.agency_id || null), uretim_tipi: form.uretim_tipi, payment_method: form.payment_method, aciklama: form.odeme_durumu === 'verecek' ? form.aciklama : null, bank_account_id: form.bank_account_id || null, branch_group: form.branch_group || null, issuing_agency_id: form.uretim_tipi === 'dis' ? (form.agency_id || null) : null }; const result = policy ? await supabase.from('policies').update(payload).eq('id', policy.id).select('id').single() : await supabase.from('policies').insert(payload).select('id').single(); if (result.error || !result.data) { setSaving(false); alert('Kayıt tamamlanamadı. Lütfen bilgileri kontrol edin.'); return; } if (form.odeme_durumu === 'verecek' && form.bank_account_id && parseAmount(form.brut_prim) > 0) { const bank = bankAccounts.find(b => b.id === form.bank_account_id); if (bank) { const newLimit = Math.max(Number(bank.card_limit || 0) - parseAmount(form.brut_prim), 0); await supabase.from('bank_accounts').update({ card_limit: newLimit }).eq('id', form.bank_account_id); } } if (file) { const path = `${result.data.id}/${Date.now()}-${file.name.replace(/[^a-zA-Z0-9._-]/g, '-')}`; const upload = await supabase.storage.from('policy-files').upload(path, file, { upsert: true }); if (upload.error) { setSaving(false); alert('Poliçe kaydedildi ancak dosya yüklenemedi.'); return; } const fileUpdate = await supabase.from('policies').update({ file_url: path, file_name: file.name }).eq('id', result.data.id); if (fileUpdate.error) { setSaving(false); alert('Poliçe kaydedildi ancak dosya bilgisi saklanamadı.'); return; } } setSaving(false); onSaved(); } return <form onSubmit={submit} className="card overflow-hidden"><div className="teal-strip">Poliçe ve Üretim Bilgileri</div><div className="p-6 grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5"><label className="field md:col-span-2 xl:col-span-3">Kayıt Tipi<select value={form.record_type} onChange={e => update('record_type', e.target.value)}><option value="uretim">Üretim</option><option value="iptal">İptal</option><option value="ek_primli_zeyil">Ek Primli Zeyil</option><option value="iadeli_zeyil">İadeli Zeyil</option><option value="primsiz_zeyil">Primsiz Zeyil</option></select></label><label className="field">Sigorta Şirketi<select required value={form.sigorta_sirketi} onChange={e => update('sigorta_sirketi', e.target.value)}><option value="">Şirket seçin</option>{companies.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}{form.sigorta_sirketi && !companies.some(c => c.name === form.sigorta_sirketi) ? <option value={form.sigorta_sirketi}>{form.sigorta_sirketi} (listede yok)</option> : null}</select></label><label className="field">Müşteri Adı / Ünvan<input required value={form.musteri_adi} onChange={e => update('musteri_adi', e.target.value)} /></label><label className="field">Poliçe No<input value={form.police_no} onChange={e => update('police_no', e.target.value)} /></label>{dupError && <div className="md:col-span-2 xl:col-span-3 text-sm text-red-600 bg-red-50 rounded-lg p-3">{dupError}</div>}<label className="field">Plaka<input value={form.plaka} onChange={e => update('plaka', e.target.value.toUpperCase())} placeholder="34 ABC 123" /></label><label className="field">Branş Grubu<select value={form.branch_group} onChange={e => update('branch_group', e.target.value)}><option value="">Seçiniz</option><option value="OTO">OTO</option><option value="KONUT">KONUT</option><option value="HAYAT">HAYAT</option><option value="DIGER">DİĞER</option></select></label><label className="field">Sigorta Türü<select value={form.sigorta_turu} onChange={e => update('sigorta_turu', e.target.value)}><option value="">Seçiniz</option>{filteredBranches.map(b => <option key={b.id} value={b.name}>{b.name}</option>)}</select></label><label className="field">Net Prim<input required inputMode="decimal" type="text" value={form.net_prim} onChange={e => update('net_prim', e.target.value)} /></label><label className="field">Brüt Prim<input required inputMode="decimal" type="text" value={form.brut_prim} onChange={e => update('brut_prim', e.target.value)} /></label><label className="field">{form.uretim_tipi === 'dis' ? 'Dış Acente' : 'Acente'}<select required value={form.agency_id} onChange={e => update('agency_id', e.target.value)}><option value="">Acente seçin</option>{agencyOptions.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}</select></label><label className="field">Üretim Tipi<select value={form.uretim_tipi} onChange={e => update('uretim_tipi', e.target.value)}><option value="ic">İç Üretim</option><option value="dis">Dış Üretim</option></select></label>{form.uretim_tipi === 'dis' && <label className="field">Kestiren Acente<select required value={form.issuing_agency_id} onChange={e => update('issuing_agency_id', e.target.value)}><option value="">Acente seçin</option>{agencyList.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}</select></label>}{form.agency_id && form.uretim_tipi === 'ic' && (() => { const agency = agencyList.find(a => a.id === form.agency_id); const rate = agency ? commissionRateFor(agency) : 0; const commission = parseAmount(form.net_prim) * rate; return <div className="field md:col-span-2 xl:col-span-3"><div className="p-3 rounded-lg bg-teal-50 border border-teal-200 text-sm"><span className="text-teal-800 font-semibold">Acente Komisyonu: </span><span className="text-teal-700">{money(commission)}</span><span className="text-teal-600 text-xs ml-2">(Net Prim × %{(rate * 100).toString().replace('.', ',')})</span></div></div>; })()}<label className="field">Ödeme Durumu<select value={form.odeme_durumu} onChange={e => { update('odeme_durumu', e.target.value); update('payment_method', e.target.value === 'verecek' ? 'VERECEK' : 'Nakit'); }}><option value="verecek">Verecek</option><option value="verdi">Verdi</option></select></label>{form.odeme_durumu === 'verdi' && <label className="field">Ödeme Yöntemi<select value={form.payment_method} onChange={e => update('payment_method', e.target.value)}><option value="Nakit">Nakit</option><option value="Kredi Kartı">Kredi Kartı</option></select></label>}{form.odeme_durumu === 'verecek' && <><label className="field">Banka Adı<select value={selectedBankName} onChange={e => { setSelectedBankName(e.target.value); update('bank_account_id', ''); }}><option value="">Banka seçin</option>{uniqueBankNames.map(bn => <option key={bn} value={bn}>{bn}</option>)}</select></label><label className="field">Hesap Adı<select value={form.bank_account_id} onChange={e => update('bank_account_id', e.target.value)}><option value="">Hesap seçin</option>{accountsForBank.map(b => <option key={b.id} value={b.id}>{b.account_name} (Limit: {money(Number(b.card_limit))})</option>)}</select></label></>}{form.odeme_durumu === 'verecek' && <label className="field md:col-span-2 xl:col-span-3">Verecek Açıklaması<textarea value={form.aciklama} onChange={e => update('aciklama', e.target.value)} placeholder="Ödeme bekleme açıklaması" rows={3} /></label>}<label className="field">Bitiş Tarihi<input required type="date" value={form.bitis_tarihi} onChange={e => update('bitis_tarihi', e.target.value)} /></label><label className="field">Başlangıç Tarihi <span className="text-[11px] font-normal text-slate-400">Bitiş tarihinden otomatik hesaplanır</span><input readOnly value={dateBeforeOneYear(form.bitis_tarihi)} /></label><label className="field">Tanzim Tarihi<input type="date" value={form.tanzim_tarihi} onChange={e => update('tanzim_tarihi', e.target.value)} /></label><label className="field md:col-span-2 xl:col-span-3">Poliçe Dosyası{policy?.file_name && <span className="text-xs text-emerald-700 mb-2">Mevcut dosya: {policy.file_name}</span>}<input type="file" accept=".pdf,.png,.jpg,.jpeg,.webp" onChange={e => setFile(e.target.files?.[0] || null)} /><span className="text-xs text-slate-400">PDF veya görsel dosyası yükleyebilirsiniz. Siz silene kadar saklanır.</span></label></div><div className="px-6 py-4 bg-slate-50 border-t flex justify-end gap-3"><button type="button" onClick={onSaved} className="btn-secondary">Vazgeç</button><button disabled={saving} className="btn-primary">{saving ? 'Kaydediliyor...' : policy ? 'Değişiklikleri Kaydet' : 'Üretimi Kaydet'}</button></div></form> }

function PolicyTable({ policies, agencies, companies, search, setSearch, onExport, onEdit, onDelete, onCancel }: { policies: Policy[]; agencies: Agency[]; companies: InsuranceCompany[]; search: string; setSearch: (s: string) => void; onExport: (type: string, rows: Policy[]) => void; onEdit: (policy: Policy) => void; onDelete: (id: string) => void; onCancel: (id: string) => void }) {
  const [month, setMonth] = useState('');
  const [year, setYear] = useState('');
  const [payFilter, setPayFilter] = useState<'all' | 'Kredi Kartı' | 'Nakit'>('all');
  const [sortBy, setSortBy] = useState<'default' | 'expiry-asc' | 'expiry-desc'>('default');
  const [prodTypeFilter, setProdTypeFilter] = useState<'all' | 'ic' | 'dis'>('all');
  const [agencyFilter, setAgencyFilter] = useState('');

  const normalizeCompanyName = (s: string) => s.replace(/İ/g, 'I').replace(/ı/g, 'i').replace(/Ş/g, 'S').replace(/ş/g, 's').replace(/Ğ/g, 'G').replace(/ğ/g, 'g').replace(/Ç/g, 'C').replace(/ç/g, 'c').replace(/Ü/g, 'U').replace(/ü/g, 'u').replace(/Ö/g, 'O').replace(/ö/g, 'o').replace(/[\t\n\r]/g, ' ').replace(/\s+/g, ' ').trim().toLowerCase();
  const companyLogoFor = (companyName: string) => { const norm = normalizeCompanyName(companyName); return companies.find(c => normalizeCompanyName(c.name) === norm)?.logo_url || null; };

  const filtered = policies.filter(p => {
    const date = new Date(p.baslangic_tarihi || p.tanzim_tarihi || p.bitis_tarihi || p.created_at);
    const matchesSearch = `${p.musteri_adi} ${p.sigorta_sirketi} ${p.police_no} ${p.plaka}`.toLowerCase().includes(search.toLowerCase());
    const matchesMonth = !month || String(date.getMonth()) === month;
    const matchesYear = !year || String(date.getFullYear()) === year;
    const matchesPay = payFilter === 'all' || (p.payment_method || 'Nakit') === payFilter;
    const matchesProdType = prodTypeFilter === 'all' || p.uretim_tipi === prodTypeFilter;
    const matchesAgency = !agencyFilter || (prodTypeFilter === 'dis' ? p.issuing_agency_id === agencyFilter : p.agency_id === agencyFilter);
    return matchesSearch && matchesMonth && matchesYear && matchesPay && matchesProdType && matchesAgency;
  });

  const sorted = [...filtered].sort((a, b) => {
    if (sortBy === 'expiry-asc') return dateDiff(a.bitis_tarihi) - dateDiff(b.bitis_tarihi);
    if (sortBy === 'expiry-desc') return dateDiff(b.bitis_tarihi) - dateDiff(a.bitis_tarihi);
    return 0;
  });

  const agencyName = (id: string | null) => agencies.find(a => a.id === id)?.name || '--';

  const daysBadge = (p: Policy) => {
    if (p.iptal) return <span className="badge bg-red-100 text-red-700">İptal</span>;
    if (!p.bitis_tarihi) return <span className="text-slate-400 text-xs">--</span>;
    const days = dateDiff(p.bitis_tarihi);
    if (days > 30) return <span className="badge green">{days} Gün</span>;
    if (days > 0) return <span className="badge orange">{days} Gün Kaldı</span>;
    return <span className="badge bg-red-100 text-red-700">Süresi Doldu</span>;
  };

  return <div className="card overflow-hidden">
    <div className="teal-strip"><span>Üretim Kayıtları <small>({sorted.length})</small></span>
      <div className="flex gap-2">
        <button onClick={() => onExport('csv', sorted)}><Download size={14} /> CSV</button>
        <button onClick={() => onExport('excel', sorted)}><FileSpreadsheet size={14} /> Excel</button>
        <button onClick={() => onExport('copy', sorted)}><Copy size={14} /> Kopyala</button>
      </div>
    </div>
    <MonthYearAccordion onChange={(nextMonth, nextYear) => { setMonth(nextMonth); setYear(nextYear); }} />
    <div className="p-4 border-b border-slate-100 flex flex-wrap items-center gap-3">
      <div className="search"><Search size={16} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Tabloda ara..." />{search && <button type="button" onClick={() => setSearch('')} className="text-slate-400 hover:text-slate-700" title="Temizle"><X size={16} /></button>}</div>
      <div className="flex items-center gap-2 ml-auto">
        <label className="flex items-center gap-1.5 text-xs font-semibold text-slate-600">
          <span>Ödeme Yöntemi:</span>
          <select value={payFilter} onChange={e => setPayFilter(e.target.value as typeof payFilter)} className="border border-slate-200 rounded-lg px-2 py-1.5 text-xs bg-white">
            <option value="all">Tümü</option>
            <option value="Kredi Kartı">Kredi Kartı</option>
            <option value="Nakit">Nakit</option>
          </select>
        </label>
        <label className="flex items-center gap-1.5 text-xs font-semibold text-slate-600">
          <span>Üretim Tipi:</span>
          <select value={prodTypeFilter} onChange={e => { setProdTypeFilter(e.target.value as typeof prodTypeFilter); setAgencyFilter(''); }} className="border border-slate-200 rounded-lg px-2 py-1.5 text-xs bg-white">
            <option value="all">Tümü</option>
            <option value="ic">Öz Üretim</option>
            <option value="dis">Dış Üretim</option>
          </select>
        </label>
        <label className="flex items-center gap-1.5 text-xs font-semibold text-slate-600">
          <span>Acente:</span>
          <select value={agencyFilter} onChange={e => setAgencyFilter(e.target.value)} className="border border-slate-200 rounded-lg px-2 py-1.5 text-xs bg-white">
            <option value="">Tüm Acenteler</option>
            {(prodTypeFilter === 'dis' ? agencies.filter(a => a.is_external) : prodTypeFilter === 'ic' ? agencies.filter(a => !a.is_external) : agencies).map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
          </select>
        </label>
        <label className="flex items-center gap-1.5 text-xs font-semibold text-slate-600">
          <span>Sıralama:</span>
          <select value={sortBy} onChange={e => setSortBy(e.target.value as typeof sortBy)} className="border border-slate-200 rounded-lg px-2 py-1.5 text-xs bg-white">
            <option value="default">Varsayılan</option>
            <option value="expiry-asc">Bitiş: Yakından Uzağa</option>
            <option value="expiry-desc">Bitiş: Uzaktan Yakına</option>
          </select>
        </label>
      </div>
    </div>
    <div className="overflow-x-auto"><table>
      <thead><tr>
        <th>Sigorta Şirketi</th><th>Müşteri</th><th>Poliçe No</th><th>Plaka</th><th>Acente</th>
        <th>Üretim</th><th>Dış Acente</th>
        <th>Sigorta Türü</th><th>Net Prim</th><th>Brüt Prim</th><th>Bitiş</th><th>Kalan Gün</th>
        <th>Ödeme Yöntemi</th><th>Dosya</th><th>Durum</th><th>İşlem</th>
      </tr></thead>
      <tbody>
        {sorted.length ? sorted.map(p => <tr key={p.id} className={p.iptal ? 'bg-red-50 text-red-700' : ''}>
          <td className="font-semibold text-slate-800"><div className="flex items-center gap-2"><CompanyLogo path={companyLogoFor(p.sigorta_sirketi)} name={p.sigorta_sirketi} size={28} /><span>{p.sigorta_sirketi}</span></div></td>
          <td>{p.musteri_adi}</td>
          <td className="font-mono text-xs">{p.police_no || '--'}</td>
          <td>{p.plaka || '--'}</td>
          <td>{agencyName(p.agency_id)}</td>
          <td>{p.uretim_tipi === 'dis' ? <span className="badge" style={{ color: '#7c3aed', background: '#f3e8ff' }}>Dış Üretim</span> : <span className="badge" style={{ color: '#0d9488', background: '#ccfbf1' }}>Öz Üretim</span>}</td>
          <td>{p.uretim_tipi === 'dis' && p.issuing_agency_id ? <span className="badge" style={{ color: '#7c3aed', background: '#f3e8ff' }}>{agencyName(p.issuing_agency_id)}</span> : '--'}</td>
          <td>{p.sigorta_turu || '--'}</td>
          <td>{money(p.net_prim)}</td>
          <td className="font-semibold">{money(p.brut_prim)}</td>
          <td>{p.bitis_tarihi || '--'}</td>
          <td>{daysBadge(p)}</td>
          <td>{(p.payment_method || 'Nakit') === 'Kredi Kartı'
            ? <span className="badge blue inline-flex items-center gap-1"><CreditCard size={12} /> Kredi Kartı</span>
            : <span className="badge inline-flex items-center gap-1" style={{ color: '#65a30d', background: '#ecfccb' }}><Banknote size={12} /> Nakit</span>}</td>
          <td>{p.file_url ? <button className="text-teal-700 hover:underline text-xs inline-flex items-center gap-1" onClick={async () => { const result = await supabase.storage.from('policy-files').createSignedUrl(p.file_url as string, 3600); if (result.data?.signedUrl) window.open(result.data.signedUrl, '_blank', 'noopener,noreferrer'); }}><FileText size={14} /> Dosyayı Gör</button> : '--'}</td>
          <td><span className={`badge ${p.iptal ? 'bg-red-100 text-red-700' : p.odeme_durumu === 'verdi' ? 'green' : 'orange'}`}>{p.iptal ? 'İptal' : p.odeme_durumu === 'verdi' ? 'Verdi' : 'Verecek'}</span></td>
          <td><div className="flex gap-1">
            <button className="icon-btn" onClick={() => onEdit(p)} title="Düzenle"><Pencil size={15} /></button>
            <button className="icon-btn danger" onClick={() => onDelete(p.id)} title="Sil"><Trash2 size={15} /></button>
            {!p.iptal && <button className="icon-btn danger" onClick={() => onCancel(p.id)} title="Poliçeyi iptal et"><X size={15} /></button>}
          </div></td>
        </tr>) : <tr><td colSpan={16} className="empty">Henüz üretim kaydı bulunmuyor.</td></tr>}
      </tbody>
    </table></div>
  </div>;
}

function AgencyManagement({ agencies, refresh }: { agencies: Agency[]; refresh: () => void }) {
  const [formOpen, setFormOpen] = useState(false);
  const [editing, setEditing] = useState<Agency | null>(null);
  const [name, setName] = useState('');
  const [rate, setRate] = useState('');
  const [busy, setBusy] = useState(false);

  function openNew() { setEditing(null); setName(''); setRate(''); setFormOpen(true); }
  function openEdit(a: Agency) { setEditing(a); setName(a.name); setRate(a.commission_rate != null ? String(a.commission_rate) : ''); setFormOpen(true); }

  async function save(e: FormEvent) {
    e.preventDefault();
    setBusy(true);
    const payload = { name: name.trim(), commission_rate: Number(rate) || 0 };
    const result = editing
      ? await supabase.from('agencies').update(payload).eq('id', editing.id)
      : await supabase.from('agencies').insert(payload);
    setBusy(false);
    if (result.error) { alert('Acente kaydedilemedi.'); return; }
    setFormOpen(false); refresh();
  }

  async function remove(id: string) {
    if (!window.confirm('Bu acenteyi silmek istediğinize emin misiniz?')) return;
    const result = await supabase.from('agencies').delete().eq('id', id);
    if (result.error) alert('Acente silinemedi. Bu acenteye bağlı poliçeler olabilir.'); else refresh();
  }

  return <div>
    <PageTitle title="Acente Yönetimi" subtitle="Acenteleri ekleyin, düzenleyin ve komisyon oranlarını belirleyin." action={<button onClick={openNew} className="btn-primary"><Plus size={17} /> Yeni Acente</button>} />
    {formOpen && <form onSubmit={save} className="card p-5 mb-5 grid grid-cols-1 sm:grid-cols-2 gap-4 max-w-xl">
      <h3 className="col-span-full font-bold">{editing ? 'Acente Düzenle' : 'Yeni Acente Ekle'}</h3>
      <label className="field">Acente İsmi<input required value={name} onChange={e => setName(e.target.value)} placeholder="Acente adını yazın" /></label>
      <label className="field">Net Prim Komisyon Yüzdesi (%)<input required type="number" step="0.01" min="0" max="100" value={rate} onChange={e => setRate(e.target.value)} placeholder="örn. 7" /></label>
      <div className="col-span-full flex justify-end gap-3"><button type="button" onClick={() => setFormOpen(false)} className="btn-secondary">Vazgeç</button><button disabled={busy} className="btn-primary">{busy ? 'Kaydediliyor...' : 'Kaydet'}</button></div>
    </form>}
    <div className="card overflow-hidden">
      <div className="teal-strip"><span>Acente Listesi <small>({agencies.length})</small></span></div>
      <div className="overflow-x-auto"><table>
        <thead><tr><th>Acente Adı</th><th>Komisyon Oranı (%)</th><th>Oluşturulma Tarihi</th><th>İşlem</th></tr></thead>
        <tbody>
          {agencies.length ? agencies.map(a => <tr key={a.id}>
            <td className="font-semibold text-slate-800">{a.name}</td>
            <td>%{a.commission_rate != null ? Number(a.commission_rate).toLocaleString('tr-TR') : '0'}</td>
            <td>{a.created_at ? new Date(a.created_at).toLocaleDateString('tr-TR') : '--'}</td>
            <td><div className="flex gap-1"><button className="icon-btn" onClick={() => openEdit(a)} title="Düzenle"><Pencil size={15} /></button><button className="icon-btn danger" onClick={() => remove(a.id)} title="Sil"><Trash2 size={15} /></button></div></td>
          </tr>) : <tr><td colSpan={4} className="empty">Henüz acente kaydı bulunmuyor.</td></tr>}
        </tbody>
      </table></div>
    </div>
  </div>;
}

function AgencyReports({ policies, agencies, onExport }: { policies: Policy[]; agencies: Agency[]; onExport: (rows: Policy[], name: string) => void }) { const [year, setYear] = useState(''); const [month, setMonth] = useState(''); const [selected, setSelected] = useState<Agency | null>(null); const months = ['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık']; const internalAgencies = agencies.filter(a => !a.is_external); const externalAgencies = agencies.filter(a => a.is_external); const periodRows = policies.filter(p => { const dateStr = p.baslangic_tarihi || p.tanzim_tarihi || p.bitis_tarihi || p.created_at; const d = new Date(dateStr); if (isNaN(d.getTime())) return true; return (!year || String(d.getFullYear()) === year) && (!month || String(d.getMonth()) === month); }); const rowsFor = (agencyId: string) => { const agency = agencies.find(a => a.id === agencyId); return periodRows.filter(p => agency?.is_external ? (p.issuing_agency_id === agencyId && p.uretim_tipi === 'dis') : (p.agency_id === agencyId)); }; const agencyCommission = (agency: Agency) => rowsFor(agency.id).filter(p => !p.iptal && p.uretim_tipi !== 'dis').reduce((a, p) => a + (p.record_type === 'iadeli_zeyil' ? -1 : 1) * Number(p.net_prim || 0) * commissionRateFor(agency), 0); return <div><PageTitle title="Acente Raporları" subtitle="Yıl ve ay seçerek acente üretimlerini ve komisyonları inceleyin." /><div className="card mb-5"><MonthYearAccordion onChange={(nextMonth, nextYear) => { setMonth(nextMonth); setYear(nextYear); }} /></div>{selected ? (selected.is_external ? <div className="card overflow-hidden"><div className="teal-strip"><button onClick={() => setSelected(null)}>‹ Acentelere Dön</button><span>{selected.name} · Dış Acente</span><button onClick={() => onExport(rowsFor(selected.id), `${selected.name}-${year}.xlsx`)}><FileSpreadsheet size={14} /> Excel</button></div><div className="overflow-x-auto"><table><thead><tr><th>Sigorta Adı</th><th>Adı</th><th>Poliçe No</th><th>Net Prim</th><th>Brüt Prim</th><th>Plaka</th><th>Bitiş Tarihi</th></tr></thead><tbody>{rowsFor(selected.id).map(p => <tr key={p.id}><td>{p.sigorta_sirketi}</td><td>{p.musteri_adi}</td><td>{p.police_no || '--'}</td><td>{money(p.net_prim)}</td><td>{money(p.brut_prim)}</td><td>{p.plaka || '--'}</td><td>{p.bitis_tarihi || '--'}</td></tr>)}</tbody></table></div></div> : <div className="card overflow-hidden"><div className="teal-strip"><button onClick={() => setSelected(null)}>‹ Acentelere Dön</button><span>{selected.name} · Komisyon Oranı: %{(commissionRateFor(selected) * 100).toString().replace('.', ',')}</span><button onClick={() => onExport(rowsFor(selected.id), `${selected.name}-${year}.xlsx`)}><FileSpreadsheet size={14} /> Excel</button></div><div className="overflow-x-auto"><table><thead><tr><th>Sigorta Adı</th><th>Adı</th><th>Poliçe No</th><th>Net Prim</th><th>Brüt Prim</th><th>Plaka</th><th>Bitiş Tarihi</th></tr></thead><tbody>{rowsFor(selected.id).map(p => <tr key={p.id}><td>{p.sigorta_sirketi}</td><td>{p.musteri_adi}</td><td>{p.police_no || '--'}</td><td>{money(p.net_prim)}</td><td>{money(p.brut_prim)}</td><td>{p.plaka || '--'}</td><td>{p.bitis_tarihi || '--'}</td></tr>)}</tbody></table></div></div>) : <><div className="mb-5"><h3 className="font-bold text-lg mb-3 text-slate-800">İç Acenteler</h3><div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5">{internalAgencies.map(agency => { const rows = rowsFor(agency.id); const inside = rows.filter(p => p.uretim_tipi === 'ic'); const outside = rows.filter(p => p.uretim_tipi === 'dis'); const rate = commissionRateFor(agency); const commission = agencyCommission(agency); return <button className="card overflow-hidden text-left hover:-translate-y-1 transition" key={agency.id} onClick={() => setSelected(agency)}><div className="teal-strip"><span>{agency.name}</span><FileSpreadsheet size={15} /></div><div className="p-5"><div className="flex items-center justify-between mb-3"><p className="text-3xl font-bold text-slate-900">{rows.length}</p><span className="text-xs font-semibold text-teal-700 bg-teal-50 px-2 py-1 rounded-lg">Komisyon %{(rate * 100).toString().replace('.', ',')}</span></div><p className="text-xs text-slate-500 mt-1">{!month ? (year || 'Tüm yıllar') : `${year || 'Tüm yıllar'} ${months[Number(month)]}`} üretimi</p><div className="flex justify-between mt-5 text-sm"><span>İç Üretimler</span><strong>{inside.length}</strong></div><div className="flex justify-between mt-2 text-sm"><span>Dış Üretimler</span><strong>{outside.length}</strong></div><div className="flex justify-between mt-4 text-sm"><span>Net prim</span><strong>{money(rows.filter(p => p.uretim_tipi !== 'dis').reduce((a, p) => a + (p.record_type === 'iadeli_zeyil' ? -1 : 1) * Number(p.net_prim || 0), 0))}</strong></div><div className="flex justify-between mt-2 text-sm"><span>Brüt prim</span><strong>{money(rows.filter(p => p.uretim_tipi !== 'dis').reduce((a, p) => a + (p.record_type === 'iadeli_zeyil' ? -1 : 1) * Number(p.brut_prim || 0), 0))}</strong></div><div className="flex justify-between mt-3 text-sm pt-3 border-t border-slate-100"><span className="font-semibold text-emerald-700">Toplam Komisyon</span><strong className="text-emerald-700">{money(commission)}</strong></div></div></button> })}</div></div><div className="mb-5"><h3 className="font-bold text-lg mb-3 text-slate-800">Dış Acenteler</h3><div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5">{externalAgencies.length ? externalAgencies.map(agency => { const rows = rowsFor(agency.id); return <button className="card overflow-hidden text-left hover:-translate-y-1 transition" key={agency.id} onClick={() => setSelected(agency)}><div className="teal-strip"><span>{agency.name}</span><FileSpreadsheet size={15} /></div><div className="p-5"><div className="flex items-center justify-between mb-3"><p className="text-3xl font-bold text-slate-900">{rows.length}</p><span className="text-xs font-semibold text-slate-600 bg-slate-100 px-2 py-1 rounded-lg">Dış Acente</span></div><p className="text-xs text-slate-500 mt-1">{!month ? (year || 'Tüm yıllar') : `${year || 'Tüm yıllar'} ${months[Number(month)]}`} üretimi</p><div className="flex justify-between mt-5 text-sm"><span>Toplam Üretim</span><strong>{rows.length}</strong></div><div className="flex justify-between mt-4 text-sm"><span>Net prim</span><strong>{money(rows.reduce((a, p) => a + (p.record_type === 'iadeli_zeyil' ? -1 : 1) * Number(p.net_prim || 0), 0))}</strong></div><div className="flex justify-between mt-2 text-sm"><span>Brüt prim</span><strong>{money(rows.reduce((a, p) => a + (p.record_type === 'iadeli_zeyil' ? -1 : 1) * Number(p.brut_prim || 0), 0))}</strong></div></div></button> }) : <div className="card p-8 text-center text-slate-400 col-span-full">Henüz dış acente kaydı bulunmuyor.</div>}</div></div></>}</div>; }







function Receivables({ policies, agencies, payments, refresh, onExport }: { policies: Policy[]; agencies: Agency[]; payments: Payment[]; refresh: () => void; onExport: (rows: Policy[], name: string) => void }) { const [selected, setSelected] = useState<Policy | null>(null); const [amount, setAmount] = useState(''); const [note, setNote] = useState(''); const [paidAt, setPaidAt] = useState(new Date().toISOString().slice(0, 10)); const [recvSearch, setRecvSearch] = useState(''); const [debtSelected, setDebtSelected] = useState<Policy | null>(null); const [debtAmount, setDebtAmount] = useState(''); const [debtNote, setDebtNote] = useState(''); const paid = (id: string) => payments.filter(x => x.policy_id === id).reduce((a, x) => a + Number(x.amount), 0); const lastPaidAt = (id: string) => { const list = payments.filter(x => x.policy_id === id).sort((a, b) => (b.paid_at || '').localeCompare(a.paid_at || '')); return list.length ? list[0].paid_at : ''; }; const isPaid = (p: Policy) => !p.iptal && paid(p.id) > 0 && Number(p.brut_prim || 0) - paid(p.id) <= 0; const allDue = policies.filter(p => p.odeme_durumu === 'verecek' || isPaid(p)); const due = [...allDue].filter(p => !recvSearch || `${p.musteri_adi} ${p.police_no || ''} ${p.plaka || ''} ${agencies.find(a => a.id === p.agency_id)?.name || ''}`.toLowerCase().includes(recvSearch.toLowerCase())).sort((a, b) => { const aPaid = isPaid(a); const bPaid = isPaid(b); if (aPaid && !bPaid) return 1; if (!aPaid && bPaid) return -1; if (aPaid && bPaid) { const aPayDate = lastPaidAt(a.id) || ''; const bPayDate = lastPaidAt(b.id) || ''; return bPayDate.localeCompare(aPayDate); } const aDate = (a.bitis_tarihi || a.tanzim_tarihi || ''); const bDate = (b.bitis_tarihi || b.tanzim_tarihi || ''); return bDate.localeCompare(aDate); }); useEffect(() => { const settledIds = policies.filter(p => !p.iptal && p.odeme_durumu === 'verecek' && Number(p.brut_prim || 0) - paid(p.id) <= 0).map(p => p.id); if (settledIds.length) void supabase.from('policies').update({ odeme_durumu: 'verdi', aciklama: null }).in('id', settledIds); }, [policies, payments]); async function addDebt(e: FormEvent) { e.preventDefault(); if (!debtSelected) return; const newDebt = Number(debtAmount); if (newDebt <= 0) { alert('Geçerli bir tutar girin.'); return; } const newBrut = Number(debtSelected.brut_prim || 0) + newDebt; const result = await supabase.from('policies').update({ brut_prim: newBrut, odeme_durumu: 'verecek', aciklama: debtNote || null }).eq('id', debtSelected.id); if (result.error) alert('Borç eklenemedi.'); else { setDebtSelected(null); setDebtAmount(''); setDebtNote(''); refresh(); } } async function addPayment(e: FormEvent) { e.preventDefault(); if (!selected) return; const result = await supabase.from('policy_payments').insert({ policy_id: selected.id, amount: Number(amount), note, paid_at: paidAt }); if (result.error) alert('Tahsilat kaydedilemedi.'); else { const totalPaid = payments.filter(x => x.policy_id === selected.id).reduce((sum, payment) => sum + Number(payment.amount || 0), 0) + Number(amount); if (totalPaid >= Number(selected.brut_prim || 0)) { const policyUpdate = await supabase.from('policies').update({ odeme_durumu: 'verdi', aciklama: null }).eq('id', selected.id); if (policyUpdate.error) { alert('Tahsilat kaydedildi ancak poliçe durumu güncellenemedi.'); } } setSelected(null); setAmount(''); setNote(''); setPaidAt(new Date().toISOString().slice(0, 10)); refresh(); } } return <div><PageTitle title="Verecekler" subtitle="Ödeme bekleyen üretimleri ve tahsilat düşümlerini yönetin." /><div className="card overflow-hidden"><div className="teal-strip"><span>Verecek Üretimler <small>({due.length})</small></span><button onClick={() => onExport(due, 'verecekler.xlsx')}><FileSpreadsheet size={14} /> Excel İndir</button></div><div className="p-4 border-b border-slate-100"><div className="search max-w-md"><Search size={16} /><input value={recvSearch} onChange={e => setRecvSearch(e.target.value)} placeholder="Müşteri, poliçe, plaka veya acente ara..." />{recvSearch && <button type="button" onClick={() => setRecvSearch('')} className="text-slate-400 hover:text-slate-700" title="Temizle"><X size={16} /></button>}</div></div><div className="overflow-x-auto"><table><thead><tr><th>Acente</th><th>Müşteri</th><th>Poliçe</th><th>Tanzim Tarihi</th><th>Açıklama</th><th>Toplam Borç</th><th>Ödenen</th><th>Son Ödeme Tarihi</th><th>Kalan</th><th>İşlem</th></tr></thead><tbody>{due.length ? due.map(p => { const amountPaid = paid(p.id); const remaining = Math.max(Number(p.brut_prim) - amountPaid, 0); const paidRow = isPaid(p); const rowStyle = p.iptal ? { background: '#FF0000', color: '#fff', fontWeight: 700 } : paidRow ? { background: '#008000', color: '#fff', fontWeight: 700 } : {}; return <tr key={p.id} style={rowStyle}><td>{agencies.find(a => a.id === p.agency_id)?.name || '--'}</td><td className="font-semibold">{p.musteri_adi}</td><td>{p.police_no || '--'}</td><td>{p.tanzim_tarihi || '--'}</td><td className="max-w-52 whitespace-normal">{p.aciklama || '--'}</td><td>{money(p.brut_prim)}</td><td>{money(amountPaid)}</td><td>{lastPaidAt(p.id) || '--'}</td><td className="font-bold">{p.iptal ? <span>{money(remaining)}</span> : paidRow ? <span>{money(remaining)}</span> : <span style={{ color: '#FF0000' }}>{money(remaining)}</span>}</td><td>{p.iptal ? <span className="badge" style={{ color: '#fff', background: 'rgba(255,255,255,.25)' }}>İptal</span> : paidRow ? <div className="flex gap-1"><span className="badge" style={{ color: '#fff', background: 'rgba(255,255,255,.25)' }}>Tamamlandı</span><button className="btn-secondary py-2 px-3" style={{ color: '#fff', borderColor: 'rgba(255,255,255,.4)' }} onClick={() => setDebtSelected(p)}><Plus size={14} /> Borç Ekle</button></div> : <div className="flex gap-1"><button className="btn-primary py-2 px-3" onClick={() => setSelected(p)}><Plus size={14} /> Düşüm Ekle</button><button className="btn-secondary py-2 px-3" onClick={() => setDebtSelected(p)}><Plus size={14} /> Borç Ekle</button></div>}</td></tr> }) : <tr><td colSpan={10} className="empty">Verecek işaretli üretim bulunmuyor.</td></tr>}</tbody></table></div></div>{debtSelected && <div className="modal-backdrop"><form onSubmit={addDebt} className="modal"><div className="flex justify-between items-center mb-5"><div><h3 className="font-bold text-lg">Borç Ekle</h3><p className="text-xs text-slate-500 mt-1">{debtSelected.musteri_adi} · Mevcut borç: {money(debtSelected.brut_prim)}</p></div><button type="button" onClick={() => setDebtSelected(null)}><X size={19} /></button></div><label className="field">Eklenecek Borç Tutarı<input required min="0.01" step="0.01" type="number" value={debtAmount} onChange={e => setDebtAmount(e.target.value)} /></label><label className="field">Açıklama<input value={debtNote} onChange={e => setDebtNote(e.target.value)} placeholder="Borç açıklaması" /></label><button className="btn-primary w-full mt-3">Borcu Ekle</button></form></div>}{selected && <div className="modal-backdrop"><form onSubmit={addPayment} className="modal"><div className="flex justify-between items-center mb-5"><div><h3 className="font-bold text-lg">Tahsilat Düşümü</h3><p className="text-xs text-slate-500 mt-1">{selected.musteri_adi} · {money(selected.brut_prim)} toplam borç</p></div><button type="button" onClick={() => setSelected(null)}><X size={19} /></button></div><label className="field">Düşülecek Tutar<input required min="0.01" step="0.01" type="number" value={amount} onChange={e => setAmount(e.target.value)} /></label><label className="field">Ödeme Tarihi<input required type="date" value={paidAt} onChange={e => setPaidAt(e.target.value)} /></label><label className="field">Açıklama<input value={note} onChange={e => setNote(e.target.value)} placeholder="Tahsilat notu" /></label><button className="btn-primary w-full mt-3">Tahsilatı Kaydet</button></form></div>}</div> }

function Customers({ customers, refresh, title = 'Kayıtlı Müşteriler' }: { customers: Customer[]; refresh: () => void; title?: string }) { const [search, setSearch] = useState(''); const [formOpen, setFormOpen] = useState(false); const [editing, setEditing] = useState<Customer | null>(null); const [detail, setDetail] = useState<Customer | null>(null); const [menu, setMenu] = useState<{ x: number; y: number; customer: Customer } | null>(null); const [noteDraft, setNoteDraft] = useState(''); const [noteSaving, setNoteSaving] = useState(false); const [noteSavedAt, setNoteSavedAt] = useState<number | null>(null); const [pasteToast, setPasteToast] = useState(''); function showPasteToast(message: string) { setPasteToast(message); window.setTimeout(() => setPasteToast(''), 4000); } function handleTcPaste(e: React.ClipboardEvent<HTMLInputElement>) { const text = e.clipboardData.getData('text'); if (!isLikelyCustomerText(text)) return; e.preventDefault(); const parsed = parseCustomerClipboard(text); const filled = countFilled(parsed); setForm(v => ({ ...v, tc_vergi_no: parsed.tcKimlikNo || v.tc_vergi_no, ad_soyad_unvan: parsed.adSoyad || v.ad_soyad_unvan, telefon: parsed.telefon || v.telefon, eposta: parsed.email || v.eposta, referans: parsed.referans || v.referans, dogum_tarihi: parsed.dogumTarihi ? `${parsed.dogumTarihi.split('.')[2]}-${parsed.dogumTarihi.split('.')[1]}-${parsed.dogumTarihi.split('.')[0]}` : v.dogum_tarihi, arac_tipi: parsed.aracTipi || v.arac_tipi, plaka_no: parsed.plakaNo || v.plaka_no, ruhsat_belge_no: parsed.ruhsatBelgeNo || v.ruhsat_belge_no, arac_yili: parsed.aracYili || v.arac_yili, arac_markasi: parsed.aracMarkasi || v.arac_markasi, arac_modeli: parsed.aracModeli || v.arac_modeli, arac_kodu: parsed.aracKodu || v.arac_kodu, motor_no: parsed.motorNo || v.motor_no, sase_no: parsed.saseNo || v.sase_no, uavt_adres_kodu: parsed.uavtAdresKodu || v.uavt_adres_kodu })); if (filled >= 8) showPasteToast('Bilgiler otomatik olarak forma aktarıldı. Lütfen kontrol edip kaydedin.'); else showPasteToast('Bazı bilgiler otomatik olarak bulunamadı. Eksik alanları kontrol edin.'); } function handleUavtPaste(e: React.ClipboardEvent<HTMLInputElement>) { const text = e.clipboardData.getData('text'); const code = extractUavtCode(text); if (code) { e.preventDefault(); setForm(v => ({ ...v, uavt_adres_kodu: code })); showPasteToast('UAVT adres kodu otomatik olarak algılandı: ' + code); } } async function saveNote(customerId: string) { setNoteSaving(true); const result = await supabase.from('customers').update({ notes: noteDraft }).eq('id', customerId); if (result.error) alert('Not kaydedilemedi.'); else { setNoteSavedAt(Date.now()); refresh(); } setNoteSaving(false); } const emptyForm = { tc_vergi_no: '', ad_soyad_unvan: '', referans: '', telefon: '', eposta: '', dogum_tarihi: '', plaka_no: '', ruhsat_belge_no: '', motor_no: '', sase_no: '', arac_yili: '', arac_markasi: '', arac_modeli: '', arac_kodu: '', arac_tipi: '', uavt_adres_kodu: '' }; const fieldLabels: Record<string, string> = { tc_vergi_no: 'TC Kimlik No', ad_soyad_unvan: 'Ad Soyad / Ünvan', referans: 'Referans', telefon: 'Telefon', eposta: 'E-Posta', dogum_tarihi: 'Doğum Tarihi', plaka_no: 'Plaka No', ruhsat_belge_no: 'Ruhsat Belge No', motor_no: 'Motor No', sase_no: 'Şase No', arac_yili: 'Araç Yılı', arac_markasi: 'Araç Markası', arac_modeli: 'Araç Modeli', arac_kodu: 'Araç Kodu', arac_tipi: 'Araç Tipi', uavt_adres_kodu: 'UAVT Adres Kodu' }; const fieldOrder = ['tc_vergi_no', 'ad_soyad_unvan', 'referans', 'telefon', 'eposta', 'dogum_tarihi', 'uavt_adres_kodu', 'arac_tipi', 'plaka_no', 'ruhsat_belge_no', 'arac_yili', 'arac_markasi', 'arac_modeli', 'arac_kodu', 'motor_no', 'sase_no']; const [form, setForm] = useState(emptyForm); const rows = customers.filter(c => !search || `${c.ad_soyad_unvan} ${c.tc_vergi_no} ${c.telefon} ${c.plaka_no}`.toLowerCase().includes(search.toLowerCase())); function openNew() { setEditing(null); setForm(emptyForm); setFormOpen(true); } function openEdit(c: Customer) { setEditing(c); setForm({ tc_vergi_no: c.tc_vergi_no || '', ad_soyad_unvan: c.ad_soyad_unvan || '', referans: c.referans || '', telefon: c.telefon || '', eposta: c.eposta || '', dogum_tarihi: c.dogum_tarihi || '', plaka_no: c.plaka_no || '', ruhsat_belge_no: c.ruhsat_belge_no || '', arac_yili: c.arac_yili || '', arac_markasi: c.arac_markasi || '', arac_modeli: c.arac_modeli || '', arac_kodu: c.arac_kodu || '', arac_tipi: c.arac_tipi || '', uavt_adres_kodu: c.uavt_adres_kodu || '', motor_no: c.motor_no || '', sase_no: c.sase_no || '' }); setFormOpen(true); } async function save(e: FormEvent) { e.preventDefault(); const uavt = form.uavt_adres_kodu?.trim(); const plaka = form.plaka_no?.trim().toUpperCase(); const dup = customers.find(c => c.id !== editing?.id && ((uavt && c.uavt_adres_kodu?.trim() === uavt) || (plaka && (c.plaka_no?.trim().toUpperCase() === plaka)))); if (dup) { alert(`Bu müşteri zaten ekli!\n\nMevcut kayıt: ${dup.ad_soyad_unvan}\n${dup.uavt_adres_kodu ? 'UAVT: ' + dup.uavt_adres_kodu : ''}${dup.plaka_no ? ' · Plaka: ' + dup.plaka_no : ''}`); return; } const result = editing ? await supabase.from('customers').update(form).eq('id', editing.id) : await supabase.from('customers').insert(form); if (result.error) alert('Müşteri kaydedilemedi.'); else { setFormOpen(false); refresh(); } } async function remove(id: string) { if (!window.confirm('Bu müşteriyi silmek istediğinize emin misiniz?')) return; const result = await supabase.from('customers').delete().eq('id', id); if (result.error) alert('Müşteri silinemedi.'); else refresh(); } useEffect(() => { if (!menu) return; const close = () => setMenu(null); window.addEventListener('click', close); window.addEventListener('contextmenu', close); return () => { window.removeEventListener('click', close); window.removeEventListener('contextmenu', close); }; }, [menu]); return <div><PageTitle title={title} />{formOpen && <form onSubmit={save} className="card p-5 mb-5 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4"><h3 className="col-span-full font-bold">{editing ? 'Müşteri Düzenle' : 'Yeni Müşteri Kaydı'}</h3>{fieldOrder.map(key => <label className="field" key={key}>{fieldLabels[key]}{key === 'tc_vergi_no' && <span className="text-[10px] text-teal-600 font-normal block mb-1">Tüm müşteri bilgilerini buraya yapıştırın (Ctrl+V)</span>}{key === 'uavt_adres_kodu' && <span className="text-[10px] text-teal-600 font-normal block mb-1">10 haneli kodu yapıştırın (otomatik algılanır)</span>}<input type={key === 'dogum_tarihi' ? 'date' : 'text'} required={key === 'ad_soyad_unvan'} value={form[key as keyof typeof form]} onChange={e => setForm(v => ({ ...v, [key]: e.target.value }))} onPaste={key === 'tc_vergi_no' ? handleTcPaste : key === 'uavt_adres_kodu' ? handleUavtPaste : undefined} /></label>)}<div className="col-span-full flex justify-end gap-3"><button type="button" onClick={() => setFormOpen(false)} className="btn-secondary">Vazgeç</button><button className="btn-primary">Kaydet</button></div></form>}<div className="card overflow-hidden"><div className="teal-strip"><span>Müşteri Listesi <small>({rows.length})</small></span><div className="flex items-center gap-2"><button onClick={openNew} className="btn-primary"><Plus size={14} /> Yeni Müşteri Ekle</button><button onClick={() => exportToCsv(rows, 'musteriler.csv')}><Download size={14} /> CSV</button></div></div><div className="p-4 border-b border-slate-100"><div className="search max-w-md"><Search size={16} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Tabloda ara..." />{search && <button type="button" onClick={() => setSearch('')} className="text-slate-400 hover:text-slate-700" title="Temizle"><X size={16} /></button>}</div></div><div className="overflow-x-auto"><table><thead><tr><th>TC Kimlik / Vergi No</th><th>Ad Soyad / Ünvan</th><th>Plaka No</th><th>Ruhsat Belge No</th><th>Telefon</th><th>E-Posta</th><th>İşlem</th></tr></thead><tbody>{rows.length ? rows.map(c => <tr key={c.id} className="cursor-pointer" onClick={() => { setDetail(c); setNoteDraft(c.notes || ''); setNoteSavedAt(null); }} onContextMenu={e => { e.preventDefault(); setMenu({ x: e.clientX, y: e.clientY, customer: c }); }}><td>{c.tc_vergi_no || '--'}</td><td className="font-semibold">{c.ad_soyad_unvan}</td><td>{c.plaka_no || '--'}</td><td>{c.ruhsat_belge_no || '--'}</td><td>{c.telefon || '--'}</td><td>{c.eposta || '--'}</td><td onClick={e => e.stopPropagation()}><div className="flex gap-1"><button className="icon-btn" onClick={() => openEdit(c)} title="Düzenle"><Pencil size={15} /></button><button className="icon-btn danger" onClick={() => remove(c.id)} title="Sil"><Trash2 size={15} /></button></div></td></tr>) : <tr><td colSpan={7} className="empty">Henüz müşteri kaydı bulunmuyor.</td></tr>}</tbody></table></div></div>{detail && <div className="modal-backdrop" onClick={() => setDetail(null)}><div className="modal" style={{ width: 'min(100%, 520px)' }} onClick={e => e.stopPropagation()}><div className="flex items-center justify-between mb-4"><h3 className="font-bold text-lg">Müşteri Detayları</h3><div className="flex items-center gap-2"><button className="icon-btn" onClick={() => setDetail(null)}><X size={18} /></button></div></div><div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-sm">{fieldOrder.map(key => <div key={key} className="p-3 rounded-lg bg-slate-50"><p className="text-xs text-slate-500 font-semibold">{fieldLabels[key]}</p><p className="font-medium text-slate-800 mt-1 break-words">{(detail[key as keyof Customer] as string) || '--'}</p></div>)}</div><div className="mt-5"><h4 className="font-bold text-sm mb-2 flex items-center gap-2"><StickyNote size={16} /> Müşteri Notları</h4><textarea className="w-full min-h-28 p-3 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-teal-500" placeholder="Bu müşteriye özel notlarınızı yazın..." value={noteDraft} onChange={e => { setNoteDraft(e.target.value); setNoteSavedAt(null); }} disabled={noteSaving} /><div className="flex items-center justify-between mt-2"><span className="text-xs text-emerald-600">{noteSavedAt ? 'Kaydedildi' : ''}</span><button className="btn-primary" onClick={() => saveNote(detail.id)} disabled={noteSaving}>{noteSaving ? 'Kaydediliyor...' : 'Notu Kaydet'}</button></div></div><div className="flex justify-end gap-3 mt-5"><button className="btn-secondary" onClick={() => { openEdit(detail); setDetail(null); }}><Pencil size={15} /> Düzenle</button><button className="btn-secondary" onClick={() => setDetail(null)}>Kapat</button></div></div></div>}{menu && <div className="fixed z-[80]" style={{ top: menu.y, left: menu.x }} onClick={e => e.stopPropagation()}><div className="card p-1 shadow-xl" style={{ minWidth: 180 }}><button className="w-full text-left px-3 py-2 rounded-md hover:bg-teal-50 text-sm flex items-center gap-2 text-slate-700" onClick={() => { setDetail(menu.customer); setNoteDraft(menu.customer.notes || ''); setNoteSavedAt(null); setMenu(null); }}><Eye size={15} /> Detayları Gör</button><button className="w-full text-left px-3 py-2 rounded-md hover:bg-teal-50 text-sm flex items-center gap-2 text-slate-700" onClick={() => { openEdit(menu.customer); setMenu(null); }}><Pencil size={15} /> Düzenle</button><button className="w-full text-left px-3 py-2 rounded-md hover:bg-red-50 text-sm flex items-center gap-2 text-red-600" onClick={() => { void remove(menu.customer.id); setMenu(null); }}><Trash2 size={15} /> Sil</button></div></div>}{pasteToast && <div className="fixed bottom-5 right-5 z-[75] rounded-lg bg-teal-700 px-4 py-3 text-sm font-semibold text-white shadow-xl animate-fade-in">{pasteToast}</div>}</div> }

type ProductionFilter = { from: string; to: string; dateField: 'baslangic_tarihi' | 'tanzim_tarihi' | 'bitis_tarihi'; company: string; type: string; plate: string; includeCancelled: boolean; inside: boolean; outside: boolean }; const emptyProductionFilter: ProductionFilter = { from: '', to: '', dateField: 'baslangic_tarihi', company: '', type: '', plate: '', includeCancelled: true, inside: true, outside: true }; function Filters({ reconciliation = false, onApply }: { reconciliation?: boolean; onApply?: (filter: ProductionFilter) => void }) { const [filter, setFilter] = useState<ProductionFilter>(emptyProductionFilter); const update = (key: keyof ProductionFilter, value: string | boolean) => setFilter(v => ({ ...v, [key]: value })); return <div className="card overflow-hidden"><div className="teal-strip">{reconciliation ? 'Mutabakat Raporu Filtreleri' : 'Üretim Filtreleri'}</div><div className="p-5 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4"><label className="field">Sigorta Şirketi<input value={filter.company} onChange={e => update('company', e.target.value)} placeholder="Şirket adını yazın" /></label><label className="field">Sigorta Türü<input value={filter.type} onChange={e => update('type', e.target.value)} placeholder="Türü yazın" /></label>{reconciliation ? <><label className="field">Yıl<input placeholder="2026" /></label><label className="field">Ay<input placeholder="Ağustos" /></label><label className="field">İş Ortağı Acentesi<input placeholder="Acente adını yazın" /></label></> : <><label className="field">Plaka<input value={filter.plate} onChange={e => update('plate', e.target.value)} placeholder="Plaka ile ara" /></label><label className="field">Başlangıç Tarihi<input type="date" value={filter.from} onChange={e => update('from', e.target.value)} /></label><label className="field">Bitiş Tarihi<input type="date" value={filter.to} onChange={e => update('to', e.target.value)} /></label><div className="field"><span>Tarih Türü</span><div className="flex flex-wrap gap-3 pt-2"><label className="radio"><input type="radio" checked={filter.dateField === 'baslangic_tarihi'} onChange={() => update('dateField', 'baslangic_tarihi')} />Başlangıç</label><label className="radio"><input type="radio" checked={filter.dateField === 'tanzim_tarihi'} onChange={() => update('dateField', 'tanzim_tarihi')} />Tanzim</label><label className="radio"><input type="radio" checked={filter.dateField === 'bitis_tarihi'} onChange={() => update('dateField', 'bitis_tarihi')} />Bitiş</label></div></div><div className="field"><span>Üretim Tipi</span><div className="flex flex-wrap gap-3 pt-2"><label className="radio"><input type="checkbox" checked={filter.inside} onChange={e => update('inside', e.target.checked)} />İç Üretim</label><label className="radio"><input type="checkbox" checked={filter.outside} onChange={e => update('outside', e.target.checked)} />Dış Üretim</label></div></div></>}<label className="radio"><input type="checkbox" checked={filter.includeCancelled} onChange={e => update('includeCancelled', e.target.checked)} />İptalleri Getir</label></div>{!reconciliation && <div className="px-5 py-4 bg-slate-50 border-t flex justify-end gap-3"><button className="btn-secondary" onClick={() => { setFilter(emptyProductionFilter); onApply?.(emptyProductionFilter); }}>Filtreleri Temizle</button><button className="btn-primary" onClick={() => onApply?.(filter)}><Search size={16} /> Filtrele</button></div>}</div> }

function Accounting() { const [entries, setEntries] = useState<Record<string, string>[]>([]); const [month, setMonth] = useState(''); const [year, setYear] = useState(''); const [form, setForm] = useState({ tip: 'tahsilat', aciklama: '', tutar: '', tarih: new Date().toISOString().slice(0, 10) }); async function add(e: FormEvent) { e.preventDefault(); const result = await supabase.from('accounting_entries').insert({ ...form, tutar: Number(form.tutar) }); if (result.error) alert('Muhasebe kaydı eklenemedi.'); else { setEntries(v => [...v, form]); setForm(v => ({ ...v, aciklama: '', tutar: '' })); } } const filteredEntries = entries.filter(entry => { const date = new Date(entry.tarih); return (!month || String(date.getMonth()) === month) && (!year || String(date.getFullYear()) === year); }); return <div><PageTitle title="Muhasebe" subtitle="Cari hareketlerinizi sıfırdan takip edin." /><div className="card mb-5"><MonthYearAccordion onChange={(nextMonth, nextYear) => { setMonth(nextMonth); setYear(nextYear); }} /></div><div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6"><StatCard title="Cari Bakiye" value="₺0" detail="Sıfırlanmış görünüm" icon={CircleDollarSign} tone="bg-teal-50 text-teal-700" /><StatCard title="Bu Ay Tahsilat" value="₺0" detail="Henüz işlem yok" icon={ArrowDownToLine} tone="bg-emerald-50 text-emerald-700" /><StatCard title="Bu Ay Ödeme" value="₺0" detail="Henüz işlem yok" icon={ArrowUpRight} tone="bg-orange-50 text-orange-700" /></div><div className="grid grid-cols-1 xl:grid-cols-3 gap-5"><form onSubmit={add} className="card p-5"><h3 className="font-bold mb-5">Yeni Cari Hareket</h3><label className="field">İşlem Türü<select value={form.tip} onChange={e => setForm(v => ({ ...v, tip: e.target.value }))}><option>tahsilat</option><option>odeme</option><option>gelir</option><option>gider</option></select></label><label className="field">Açıklama<input required value={form.aciklama} onChange={e => setForm(v => ({ ...v, aciklama: e.target.value }))} /></label><label className="field">Tutar<input required type="number" value={form.tutar} onChange={e => setForm(v => ({ ...v, tutar: e.target.value }))} /></label><label className="field">Tarih<input type="date" value={form.tarih} onChange={e => setForm(v => ({ ...v, tarih: e.target.value }))} /></label><button className="btn-primary w-full">Hareket Ekle</button></form><div className="card xl:col-span-2 overflow-hidden"><div className="teal-strip">Cari Hareketler</div><table><thead><tr><th>Tarih</th><th>Tür</th><th>Açıklama</th><th>Tutar</th></tr></thead><tbody>{filteredEntries.length ? filteredEntries.map((e, i) => <tr key={i}><td>{e.tarih}</td><td>{e.tip}</td><td>{e.aciklama}</td><td>{money(Number(e.tutar))}</td></tr>) : <tr><td colSpan={4} className="empty">Henüz cari hareket bulunmuyor.</td></tr>}</tbody></table></div></div></div> }

function SimpleList({ type }: { type: 'damage' | 'staff' | 'calendar' }) { const configs = { damage: { title: 'Hasar Kayıtları', fields: ['Müşteri Adı', 'Poliçe No', 'Araç Plaka', 'Hasar Tarihi', 'Hasar Tutarı', 'Durum'] }, staff: { title: 'Personel İşlemleri', fields: ['Ad Soyad', 'Görevi', 'Telefon', 'E-Posta', 'Bağlı Acente'] }, calendar: { title: 'Takvim ve Hatırlatmalar', fields: ['Tarih', 'Başlık', 'Açıklama', 'Durum'] } }; const c = configs[type]; const [rows, setRows] = useState<Record<string, string>[]>([]); const [form, setForm] = useState<Record<string, string>>({}); const [open, setOpen] = useState(false); return <div><PageTitle title={c.title} action={<button className="btn-primary" onClick={() => setOpen(true)}><Plus size={17} /> Yeni Kayıt</button>} />{open && <div className="card p-5 mb-5 grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4"><h3 className="font-bold col-span-full">Yeni Kayıt</h3>{c.fields.map(f => <label className="field" key={f}>{f}<input value={form[f] || ''} onChange={e => setForm(v => ({ ...v, [f]: e.target.value }))} /></label>)}<div className="col-span-full flex justify-end gap-3"><button className="btn-secondary" onClick={() => setOpen(false)}>Vazgeç</button><button className="btn-primary" onClick={() => { setRows(v => [...v, form]); setOpen(false); setForm({}); }}>Kaydet</button></div></div>}<div className="card overflow-hidden"><div className="teal-strip">{c.title} <small>({rows.length})</small></div><table><thead><tr>{c.fields.map(f => <th key={f}>{f}</th>)}</tr></thead><tbody>{rows.length ? rows.map((r, i) => <tr key={i}>{c.fields.map(f => <td key={f}>{r[f] || '--'}</td>)}</tr>) : <tr><td colSpan={c.fields.length} className="empty">Henüz kayıt bulunmuyor.</td></tr>}</tbody></table></div></div> }

function SettingsPage({ backupData, onRestore, onToast }: { backupData: BackupData; onRestore: (data: BackupData) => Promise<void>; onToast: (message: string) => void }) {
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState('');
  const [autoBackup, setAutoBackup] = useState(() => localStorage.getItem('auto_backup_enabled') !== 'false');
  const [file, setFile] = useState<File | null>(null);
  const [showWarning, setShowWarning] = useState(false);
  const [parsedData, setParsedData] = useState<BackupData | null>(null);
  function saveAutoBackup(value: boolean) { setAutoBackup(value); localStorage.setItem('auto_backup_enabled', String(value)); }
  async function backup() {
    setBusy(true); setMessage('');
    const additional: Record<string, Record<string, unknown>[]> = {};
    for (const table of ['damage_records', 'staff', 'reminders']) { const result = await supabase.from(table).select('*'); if (!result.error && result.data) additional[table] = result.data as Record<string, unknown>[]; }
    const payload = { ...backupData, additional, exportedAt: new Date().toISOString() };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob); const a = document.createElement('a');
    a.href = url; a.download = `sigorta_yedek_${new Date().toISOString().slice(0, 10)}.json`; a.click(); URL.revokeObjectURL(url);
    setBusy(false); setMessage('Yedekleme başarıyla tamamlandı.'); onToast('Yedekleme başarıyla tamamlandı');
  }
  function onFileChange(e: React.ChangeEvent<HTMLInputElement>) { setFile(e.target.files?.[0] || null); }
  async function parseAndConfirm(e: FormEvent) {
    e.preventDefault(); if (!file) return;
    setBusy(true); setMessage('');
    try {
      const data = JSON.parse(await file.text()) as Partial<BackupData>;
      if (!data || typeof data !== 'object') throw new Error('Dosya boş veya okunamadı.');
      if (!Array.isArray(data.policies) && !Array.isArray(data.customers) && !Array.isArray(data.agencies)) throw new Error('Yedek dosyasında veri bulunamadı.');
      setParsedData({ exportedAt: data.exportedAt || new Date().toISOString(), policies: Array.isArray(data.policies) ? data.policies : [], customers: Array.isArray(data.customers) ? data.customers : [], agencies: Array.isArray(data.agencies) ? data.agencies : [], payments: Array.isArray(data.payments) ? data.payments : [], accounting: Array.isArray(data.accounting) ? data.accounting : [], additional: data.additional || {} });
      setShowWarning(true);
    } catch (err) { setMessage('Geri yükleme başarısız. ' + (err instanceof Error ? err.message : 'Dosya geçerli bir yedek değil.')); }
    setBusy(false);
  }
  async function confirmRestore() {
    if (!parsedData) return;
    setShowWarning(false); setBusy(true); setMessage('');
    try {
      await onRestore(parsedData);
      setMessage('Yedek başarıyla geri yüklendi.'); onToast('Yedekleme başarıyla tamamlandı');
      setFile(null);
    } catch (err) { setMessage('Geri yükleme başarısız. ' + (err instanceof Error ? err.message : 'Bir hata oluştu.')); }
    setBusy(false);
  }
  return <div><PageTitle title="Ayarlar" subtitle="Hesap bilgilerinizi ve veri yedeklerini yönetin." />
    <div className="card p-6 mb-5"><p className="text-xs uppercase tracking-wider text-slate-400 font-semibold">Hesap</p><h3 className="font-bold text-lg mt-2">Güvenlik ayarları</h3><p className="text-sm text-slate-500 mt-1">Şifrenizi giriş ekranındaki "Şifremi Unuttum?" bağlantısından yenileyebilirsiniz.</p></div>
    <div className="card p-6"><div className="flex items-center justify-between gap-4"><div><p className="text-xs uppercase tracking-wider text-slate-400 font-semibold">Veri Yedekleme</p><h3 className="font-bold text-lg mt-2">Yedekle ve Geri Yükle</h3></div><button type="button" onClick={() => saveAutoBackup(!autoBackup)} className={`relative h-6 w-11 rounded-full transition ${autoBackup ? 'bg-teal-600' : 'bg-slate-300'}`} aria-label="Otomatik yedeklemeyi değiştir"><span className={`absolute top-1 size-4 rounded-full bg-white transition ${autoBackup ? 'left-6' : 'left-1'}`} /></button></div><p className="text-sm text-slate-500 mt-1 mb-1">Otomatik Yedekleme: <strong>{autoBackup ? 'Açık' : 'Kapalı'}</strong></p><p className="text-sm text-slate-500 mt-4 mb-5">Tüm poliçe, müşteri, acente, tahsilat ve muhasebe verilerinizi JSON dosyası olarak kaydedin veya geri yükleyin.</p>
    <div className="flex flex-wrap gap-3"><button disabled={busy} onClick={backup} className="btn-primary"><Download size={16} /> Sistem Yedeğini İndir</button><form onSubmit={parseAndConfirm} className="inline-flex items-center gap-3"><label className="btn-secondary cursor-pointer"><Upload size={16} /> Yedek Dosyası Seç<input name="file" type="file" accept=".json,application/json" className="hidden" onChange={onFileChange} /></label><button disabled={busy || !file} type="submit" className="btn-secondary">Yedek Yükle</button></form></div>
    {file && <p className="text-xs text-slate-500 mt-3">Seçilen dosya: {file.name}</p>}{message && <div className="text-sm mt-4 p-3 rounded-lg bg-teal-50 text-teal-700">{message}</div>}
    <div className="mt-5 grid grid-cols-2 sm:grid-cols-4 gap-4 text-center"><div className="p-4 rounded-xl bg-slate-50"><p className="text-2xl font-bold text-slate-900">{backupData.policies.length}</p><p className="text-xs text-slate-500 mt-1">Poliçe</p></div><div className="p-4 rounded-xl bg-slate-50"><p className="text-2xl font-bold text-slate-900">{backupData.customers.length}</p><p className="text-xs text-slate-500 mt-1">Müşteri</p></div><div className="p-4 rounded-xl bg-slate-50"><p className="text-2xl font-bold text-slate-900">{backupData.agencies.length}</p><p className="text-xs text-slate-500 mt-1">Acente</p></div><div className="p-4 rounded-xl bg-slate-50"><p className="text-2xl font-bold text-slate-900">{backupData.payments.length}</p><p className="text-xs text-slate-500 mt-1">Tahsilat</p></div></div></div>
    {showWarning && <div className="modal-backdrop"><div className="modal" style={{ width: 'min(100%, 480px)' }}><div className="text-center"><div className="mx-auto size-14 rounded-full bg-red-100 flex items-center justify-center mb-4"><AlertTriangle size={28} className="text-red-600" /></div><h3 className="font-bold text-lg text-slate-900">DİKKAT!</h3><p className="text-sm text-slate-600 mt-3 leading-relaxed">Yüklenen yedek mevcut verilerin <strong>üzerine yazılacak</strong> ve mevcut veriler <strong>silenecektir</strong>! Devam etmek istiyor musunuz?</p></div><div className="flex gap-3 mt-6"><button className="btn-secondary flex-1" onClick={() => { setShowWarning(false); setParsedData(null); }}>Vazgeç</button><button className="btn-primary flex-1" style={{ background: '#dc2626' }} onClick={confirmRestore}>Evet, Devam Et</button></div></div></div>}
  </div> }

export default function App() { const [session, setSession] = useState<Session | null>(null); const [loading, setLoading] = useState(true); const [darkMode, setDarkMode] = useState(() => localStorage.getItem('mine-theme') === 'dark'); const [spotlightOpen, setSpotlightOpen] = useState(false); const [page, setPage] = useState<Page>('dashboard'); const [policies, setPolicies] = useState<Policy[]>([]); const [customers, setCustomers] = useState<Customer[]>([]); const [agencyList, setAgencyList] = useState<Agency[]>([]); const [payments, setPayments] = useState<Payment[]>([]); const [accounting, setAccounting] = useState<Record<string, unknown>[]>([]); const [backupToast, setBackupToast] = useState(''); const [search, setSearch] = useState(''); const [editingPolicy, setEditingPolicy] = useState<Policy | undefined>(); const [productionFilter, setProductionFilter] = useState<ProductionFilter>(emptyProductionFilter); const [sidebarCollapsed, setSidebarCollapsed] = useState(() => localStorage.getItem('sidebar_collapsed') === 'true'); const [insuranceCompanies, setInsuranceCompanies] = useState<InsuranceCompany[]>([]); const [insuranceBranches, setInsuranceBranches] = useState<InsuranceBranch[]>([]); const [bankAccounts, setBankAccounts] = useState<BankAccount[]>([]); const [subAgentsList, setSubAgentsList] = useState<SubAgent[]>([]); const [quotesList, setQuotesList] = useState<Quote[]>([]); const [quoteItemsList, setQuoteItemsList] = useState<QuoteItem[]>([]); const [lostCustomersList, setLostCustomersList] = useState<LostCustomer[]>([]); const [damageRecordsList, setDamageRecordsList] = useState<DamageRecord[]>([]); const [remindersList, setRemindersList] = useState<Reminder[]>([]); const [agencyProfile, setAgencyProfile] = useState<AgencyProfile | null>(null); const [bulkImportOpen, setBulkImportOpen] = useState(false); useEffect(() => { supabase.auth.getSession().then(({ data }) => { setSession(data.session); setLoading(false); }); const { data } = supabase.auth.onAuthStateChange((_event, s) => setSession(s)); return () => data.subscription.unsubscribe(); }, []); const load = async () => { const [p, c, a, pay, acc, comp, bran, bank, sub, quo, qi, lost, dmg, rem] = await Promise.all([supabase.from('policies').select('*').order('created_at', { ascending: false }), supabase.from('customers').select('*').order('created_at', { ascending: false }), supabase.from('agencies').select('*').order('name'), supabase.from('policy_payments').select('*').order('created_at', { ascending: false }), supabase.from('accounting_entries').select('*').order('created_at', { ascending: false }), supabase.from('insurance_companies').select('*').order('name'), supabase.from('insurance_branches').select('*').order('name'), supabase.from('bank_accounts').select('*').order('bank_name'), supabase.from('sub_agents').select('*').order('name'), supabase.from('quotes').select('*').order('created_at', { ascending: false }), supabase.from('quote_items').select('*').order('created_at', { ascending: false }), supabase.from('lost_customers').select('*').order('created_at', { ascending: false }), supabase.from('damage_records').select('*').order('created_at', { ascending: false }), supabase.from('reminders').select('*').order('created_at', { ascending: false })]); if (!p.error) setPolicies(p.data as Policy[]); if (!c.error) setCustomers(c.data as Customer[]); if (!a.error) { if (!a.data.length) { await supabase.from('agencies').insert(agencyNames.map(name => ({ name }))); const refreshed = await supabase.from('agencies').select('*').order('name'); if (!refreshed.error) setAgencyList(refreshed.data as Agency[]); } else setAgencyList(a.data as Agency[]); } if (!pay.error) setPayments(pay.data as Payment[]); if (!acc.error) setAccounting(acc.data as Record<string, unknown>[]); if (!comp.error) setInsuranceCompanies(comp.data as InsuranceCompany[]); if (!bran.error) setInsuranceBranches(bran.data as InsuranceBranch[]); if (!bank.error) setBankAccounts(bank.data as BankAccount[]); if (!sub.error) setSubAgentsList(sub.data as SubAgent[]); if (!quo.error) setQuotesList(quo.data as Quote[]); if (!qi.error) setQuoteItemsList(qi.data as QuoteItem[]); if (!lost.error) setLostCustomersList(lost.data as LostCustomer[]); if (!dmg.error) setDamageRecordsList(dmg.data as DamageRecord[]); if (!rem.error) setRemindersList(rem.data as Reminder[]); const ap = await supabase.from('agency_profiles').select('*').maybeSingle(); if (!ap.error && ap.data) setAgencyProfile(ap.data as AgencyProfile); }; useEffect(() => { document.documentElement.classList.toggle('dark', darkMode); localStorage.setItem('mine-theme', darkMode ? 'dark' : 'light'); }, [darkMode]); useEffect(() => { if (session) { (async () => { const { data: existing } = await supabase.from('profiles').select('id').eq('id', session.user.id).maybeSingle(); if (!existing) { const { error: insErr } = await supabase.from('profiles').insert({ id: session.user.id, full_name: session.user.user_metadata?.full_name || null }); if (insErr) console.error('Profil otomatik oluşturulamadı:', insErr.message); } })(); load(); } }, [session]); useEffect(() => { if (session && localStorage.getItem('auto_backup_enabled') !== 'false') localStorage.setItem('auto_backup_latest', JSON.stringify({ exportedAt: new Date().toISOString(), policies, customers, agencies: agencyList, payments, accounting, additional: {} })); }, [session, policies, customers, agencyList, payments, accounting]); useEffect(() => { const onKeyDown = (event: KeyboardEvent) => { if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); setSpotlightOpen(value => !value); } }; window.addEventListener('keydown', onKeyDown); return () => window.removeEventListener('keydown', onKeyDown); }, []); useEffect(() => { localStorage.setItem('sidebar_collapsed', String(sidebarCollapsed)); }, [sidebarCollapsed]); const exportRows = (rows: Policy[]) => rows.map(p => ({ 'sigorta adı': p.sigorta_sirketi, 'müşteri adı': p.musteri_adi, 'poliçe no': p.police_no, plaka: p.plaka, 'net prim': p.net_prim, 'brüt prim': p.brut_prim, 'bitiş tarihi': p.bitis_tarihi })); const handleExport = (rows: Policy[], name: string) => exportToExcel(exportRows(rows), name); async function cancelPolicy(id: string) { if (!window.confirm('Bu poliçeyi iptal etmek istediğinize emin misiniz?')) return; const result = await supabase.from('policies').update({ iptal: true, net_prim: 0, brut_prim: 0 }).eq('id', id); if (!result.error) load(); else alert('Poliçe iptal edilemedi.'); } async function deletePolicy(id: string) { if (!window.confirm('Bu üretim kaydını silmek istediğinize emin misiniz?')) return; const result = await supabase.from('policies').delete().eq('id', id); if (!result.error) load(); else alert('Kayıt silinemedi.'); } async function restoreBackup(data: BackupData) {
    const tables: [string, Record<string, unknown>[]][] = [
      ['agencies', data.agencies],
      ['customers', data.customers],
      ['policies', data.policies],
      ['policy_payments', data.payments],
      ['accounting_entries', data.accounting],
      ...Object.entries(data.additional),
    ];
    const errors: string[] = [];
    for (const [table, rows] of tables) {
      if (!Array.isArray(rows) || rows.length === 0) continue;
      const sanitized = rows.map(({ user_id, ...rest }) => rest);
      const inserted = await supabase.from(table).insert(sanitized);
      if (inserted.error) errors.push(`${table}: ${inserted.error.message}`);
    }
    if (errors.length) throw new Error(errors.join('; '));
    await load();
  } function openPolicy(id: string) { const policy = policies.find(item => item.id === id); if (policy) { setEditingPolicy(policy); setPage('new-policy'); } setSpotlightOpen(false); } if (window.location.pathname === '/reset-password') return <ResetPasswordScreen />; if (loading) return <div className="min-h-screen bg-slate-950 flex items-center justify-center text-teal-300">Yükleniyor...</div>; if (!session) return <AuthScreen onDone={() => setPage('dashboard')} />; const filterProduction = (rows: Policy[]) => rows.filter(p => { const value = p[productionFilter.dateField] || ''; const inDateRange = (!productionFilter.from || value >= productionFilter.from) && (!productionFilter.to || value <= productionFilter.to); const matchesType = (productionFilter.inside && p.uretim_tipi === 'ic') || (productionFilter.outside && p.uretim_tipi === 'dis'); return (productionFilter.includeCancelled || !p.iptal) && inDateRange && matchesType && (!productionFilter.company || p.sigorta_sirketi.toLowerCase().includes(productionFilter.company.toLowerCase())) && (!productionFilter.type || (p.sigorta_turu || '').toLowerCase().includes(productionFilter.type.toLowerCase())) && (!productionFilter.plate || (p.plaka || '').toLowerCase().includes(productionFilter.plate.toLowerCase())); }); const savePolicy = () => { setEditingPolicy(undefined); load(); setPage('policies'); }; const content = page === 'dashboard' ? <Dashboard setPage={setPage} policies={policies} customers={customers} agencies={agencyList} /> : page === 'new-policy' ? <><PageTitle title={editingPolicy ? 'Poliçe Düzenle' : 'Yeni Poliçe Ekle'} subtitle="Üretim bilgilerini girin. Başlangıç tarihi bitiş tarihinden otomatik hesaplanır." /><PolicyForm policy={editingPolicy} agencies={agencyList} onSaved={savePolicy} policies={policies} companies={insuranceCompanies} branches={insuranceBranches} bankAccounts={bankAccounts} /></> : page === 'policies' ? <><PageTitle title="Tüm Poliçeler" action={<div className="flex gap-2"><button onClick={() => setBulkImportOpen(true)} className="btn-secondary"><Upload size={17} /> Excel'den Aktar</button><button onClick={() => { setEditingPolicy(undefined); setPage('new-policy'); }} className="btn-primary"><Plus size={17} /> Yeni Poliçe</button></div>} /><PolicyTable policies={policies} agencies={agencyList} companies={insuranceCompanies} search={search} setSearch={setSearch} onEdit={p => { setEditingPolicy(p); setPage('new-policy'); }} onDelete={deletePolicy} onCancel={cancelPolicy} onExport={(type, rows) => type === 'excel' ? handleExport(rows, 'mine-akkurt-uretimleri.xlsx') : type === 'csv' ? exportToCsv(exportRows(rows), 'mine-akkurt-uretimleri.csv') : navigator.clipboard?.writeText(JSON.stringify(exportRows(rows)))} /></> : page === 'auto-register' ? <AutoRegistrationPage customers={customers} refresh={load} /> : page === 'customers' ? <Customers customers={customers} refresh={load} /> : page === 'insured-customers' ? <Customers customers={customers.filter(c => policies.some(p => p.musteri_adi === c.ad_soyad_unvan))} refresh={load} title="Poliçesi Bulunanlar" /> : page === 'lost-customers' ? <LostCustomersPage lostCustomers={lostCustomersList} branches={insuranceBranches} refresh={load} /> : page === 'agencies' ? <AgencyReports policies={policies} agencies={agencyList} onExport={handleExport} /> : page === 'agency-management' ? <AgencyManagement agencies={agencyList.filter(a => !a.is_external)} refresh={load} /> : page === 'external-agencies' ? <ExternalAgentsPage agencies={agencyList} refresh={load} /> : page === 'receivables' ? <Receivables policies={policies} agencies={agencyList} payments={payments} refresh={load} onExport={handleExport} /> : page === 'production' ? <div><PageTitle title="Üretim Sorgula" /><Filters onApply={setProductionFilter} /><div className="mt-5"><PolicyTable policies={filterProduction(policies)} agencies={agencyList} companies={insuranceCompanies} search={search} setSearch={setSearch} onEdit={p => { setEditingPolicy(p); setPage('new-policy'); }} onDelete={deletePolicy} onCancel={cancelPolicy} onExport={(type, rows) => type === 'excel' ? handleExport(rows, 'uretim-sorgu.xlsx') : exportToCsv(exportRows(rows), 'uretim-sorgu.csv')} /></div></div> : page === 'reconciliation' ? <div><PageTitle title="Mutabakat Raporu" /><Filters reconciliation /><div className="flex justify-end gap-3 mt-5"><button onClick={() => exportToPdf(exportRows(policies), 'Mutabakat Raporu')} className="btn-secondary"><FileText size={16} /> Mutabakat PDF Raporu Al</button><button onClick={() => handleExport(policies, 'mutabakat-raporu.xlsx')} className="btn-primary"><FileSpreadsheet size={16} /> Mutabakat Excel Raporu Al</button></div></div> : page === 'accounting' ? <Accounting /> : page === 'companies' ? <CompaniesPage companies={insuranceCompanies} refresh={load} /> : page === 'branches' ? <BranchesPage branches={insuranceBranches} refresh={load} /> : page === 'banks' ? <BanksPage banks={bankAccounts} refresh={load} /> : page === 'sub-agents' ? <SubAgentsPage subAgents={subAgentsList} refresh={load} /> : page === 'quotes' ? <QuotesPage quotes={quotesList} quoteItems={quoteItemsList} companies={insuranceCompanies} branches={insuranceBranches} agencies={agencyList} customers={customers} refresh={load} /> : page === 'reminders' ? <RemindersPage reminders={remindersList} refresh={load} /> : page === 'account-statement' ? <AccountStatementPage policies={policies} payments={payments} agencies={agencyList} /> : page === 'damage' ? <DamageRecordsPage damageRecords={damageRecordsList} refresh={load} /> : page === 'new-damage' ? <DamageRecordsPage damageRecords={damageRecordsList} refresh={load} /> : page === 'staff' ? <SimpleList type="staff" /> : page === 'calendar' ? <SimpleList type="calendar" /> : page === 'agency-settings' ? <AgencySettingsPage profile={agencyProfile} refresh={load} /> : page === 'settings' ? <SettingsPage backupData={{ exportedAt: new Date().toISOString(), policies, customers, agencies: agencyList, payments, accounting, additional: {} }} onRestore={restoreBackup} onToast={message => { setBackupToast(message); window.setTimeout(() => setBackupToast(''), 2800); }} /> : editingPolicy ? <><PageTitle title="Poliçe Düzenle" /><PolicyForm policy={editingPolicy} agencies={agencyList} onSaved={savePolicy} policies={policies} companies={insuranceCompanies} branches={insuranceBranches} bankAccounts={bankAccounts} /></> : <Dashboard setPage={setPage} policies={policies} customers={customers} agencies={agencyList} />; const userName = session.user.user_metadata?.full_name || session.user.email?.split('@')[0] || 'Yetkili'; return <div className="min-h-screen bg-slate-100 text-slate-800"><Sidebar page={page} setPage={setPage} onLogout={() => supabase.auth.signOut()} userName={userName} agencyProfile={agencyProfile} collapsed={sidebarCollapsed} onToggleCollapse={() => setSidebarCollapsed(v => !v)} /><main className={`main ${sidebarCollapsed ? 'expanded' : ''}`}><TopBar page={page} userName={userName} darkMode={darkMode} onToggleTheme={() => setDarkMode(value => !value)} policies={policies} onNavigate={openPolicy} agencyProfile={agencyProfile} /><div className="p-5 sm:p-7 max-w-[1600px] mx-auto">{content}</div></main>{spotlightOpen && <SpotlightSearch policies={policies} onNavigate={openPolicy} onClose={() => setSpotlightOpen(false)} />}{backupToast && <div className="fixed bottom-5 right-5 z-[70] rounded-lg bg-slate-900 px-4 py-3 text-sm font-semibold text-white shadow-xl">{backupToast}</div>}<BulkImportModal open={bulkImportOpen} onClose={() => setBulkImportOpen(false)} existingPolicies={policies} onDone={load} agencies={agencyList} defaultAgencyId={agencyList.find(a => !a.is_external)?.id ?? null} /><ContextMenu /></div> }
